-- Psychology, corrected.
--
-- Two faults, both measured before the rewrite:
--
--   1. The correct answer was the strictly longest of the four options in
--      501 of 602 questions (83.2%, against 25% by chance), because the bank
--      used one template throughout -- a full definition as the answer beside
--      three short dismissals. The category could be won without reading the
--      prompt. Distractors are now real definitions of neighbouring concepts,
--      in the same grammatical form and within a few words of the answer, which
--      brings the rate to roughly 23% -- indistinguishable from chance. Tuning
--      it to zero would only have created the opposite tell.
--
--   2. 97 questions (16%) asked who discovered or ran something rather than how
--      the mind works, including a whole subject label, "Famous Names and
--      Studies". Those are converted, not deleted -- the question now asks about
--      the mechanism the name was attached to -- so no question is lost.
--
-- 576 rows are updated in place by id. Nothing is inserted or deactivated.
update public.quiz_questions as question
set prompt = fix.item ->> 'p',
    correct_answer = fix.item ->> 'a',
    wrong_answers = array(select jsonb_array_elements_text(fix.item -> 'w')),
    subject = fix.item ->> 's'
from jsonb_array_elements($fixes$
[
  {"a": "Keeping breathing and heartbeat going", "id": "psychology_0001", "p": "What is the main job of the brain stem?", "s": "The Brain", "w": ["Turning sensory signals into perception", "Storing the memories of your own life", "Planning actions and holding back urges"], "why": "both"},
  {"a": "Form new memories", "id": "psychology_0003", "p": "What does the hippocampus help you do?", "s": "The Brain", "w": ["Control hunger and thirst", "Keep your balance steady", "Recognise familiar faces"], "why": "implausible-distractors"},
  {"a": "The folded outer layer of the brain", "id": "psychology_0005", "p": "What is the cortex?", "s": "The Brain", "w": ["The fluid-filled spaces inside the brain", "The band of fibres joining the halves", "The stalk joining the brain to the spine"], "why": "both"},
  {"a": "Hunger, thirst, and body heat", "id": "psychology_0007", "p": "What does the hypothalamus help control?", "s": "The Brain", "w": ["Balance, posture, and smooth movement", "Speech, reading, and writing", "Vision, colour, and motion"], "why": "both"},
  {"a": "The right side of the body", "id": "psychology_0008", "p": "The left side of the brain mostly controls which side?", "s": "The Brain", "w": ["The left side of the body", "Both sides of the body equally", "Only the face and the neck"], "why": "implausible-distractors"},
  {"a": "The band of fibres joining the two halves", "id": "psychology_0009", "p": "What is the corpus callosum?", "s": "The Brain", "w": ["The fluid-filled chambers inside the brain", "The outer layer where thinking happens", "The relay station for incoming senses"], "why": "both"},
  {"a": "Planning and self-control", "id": "psychology_0010", "p": "What is the frontal lobe best known for?", "s": "The Brain", "w": ["Hearing and understanding speech", "Seeing shapes and colour", "Feeling touch on the skin"], "why": "both"},
  {"a": "Understand speech", "id": "psychology_0015", "p": "What does Wernicke's area help you do?", "s": "The Brain", "w": ["Produce fluent speech", "Recognise faces", "Judge distance"], "why": "length-tell"},
  {"a": "The brain can change and adapt", "id": "psychology_0016", "p": "What does neuroplasticity mean?", "s": "The Brain", "w": ["The brain stops changing after birth", "The brain grows new lobes with age", "The brain works as one single unit"], "why": "implausible-distractors"},
  {"a": "About 1.4 kilograms", "id": "psychology_0017", "p": "About how much does an adult brain weigh?", "s": "The Brain", "w": ["About 2.8 kilograms", "About 0.7 kilograms", "About 4.2 kilograms"], "why": "implausible-distractors"},
  {"a": "Electrical waves in the brain", "id": "psychology_0018", "p": "What does an EEG measure?", "s": "The Brain", "w": ["Blood flow through brain areas", "The thickness of the cortex", "The speed of a reflex action"], "why": "both"},
  {"a": "Which brain areas are busy", "id": "psychology_0019", "p": "What does an fMRI scan show?", "s": "The Brain", "w": ["Which chemicals a neuron releases", "How fast a nerve signal travels", "How many neurons a person has"], "why": "both"},
  {"a": "Releasing hormones", "id": "psychology_0020", "p": "What is the job of the pituitary gland?", "s": "The Brain", "w": ["Storing long-term memories", "Filtering waste from blood", "Controlling fine movement"], "why": "both"},
  {"a": "The brain and spinal cord", "id": "psychology_0021", "p": "What is the central nervous system made of?", "s": "The Brain", "w": ["The nerves in the arms and legs", "The brain and the sense organs", "The spinal cord and the muscles"], "why": "both"},
  {"a": "Prepares the body for action", "id": "psychology_0022", "p": "What does the sympathetic nervous system do?", "s": "The Brain", "w": ["Carries touch signals to the brain", "Calms the body after a scare", "Controls voluntary movement"], "why": "both"},
  {"a": "Calms the body down", "id": "psychology_0023", "p": "What does the parasympathetic nervous system do?", "s": "The Brain", "w": ["Speeds the heart rate up", "Raises the blood pressure", "Widens the pupils quickly"], "why": "implausible-distractors"},
  {"a": "A fast automatic response", "id": "psychology_0024", "p": "What is a reflex?", "s": "The Brain", "w": ["A planned voluntary action", "A signal sent by a hormone", "A slowly learned habit"], "why": "both"},
  {"a": "In the spinal cord", "id": "psychology_0025", "p": "Where are many simple reflexes handled?", "s": "The Brain", "w": ["In the frontal lobe", "In the cerebellum", "In the thalamus"], "why": "implausible-distractors"},
  {"a": "Nerve cell bodies", "id": "psychology_0026", "p": "What is grey matter mostly made of?", "s": "The Brain", "w": ["Long myelin-covered fibres", "Fluid that cushions the brain", "Cells that support neurons"], "why": "implausible-distractors"},
  {"a": "Keeps many harmful substances out", "id": "psychology_0027", "p": "What does the blood-brain barrier do?", "s": "The Brain", "w": ["Controls how fast nerve signals travel", "Cushions the brain against knocks", "Carries oxygen to every neuron"], "why": "both"},
  {"a": "A loss of blood flow to the brain", "id": "psychology_0028", "p": "What is a stroke?", "s": "The Brain", "w": ["A sudden burst of electrical activity", "A slow loss of nerve cells with age", "A swelling of the fluid spaces"], "why": "both"},
  {"a": "Each half works without the other", "id": "psychology_0029", "p": "What happens when the two brain halves are separated?", "s": "The Brain", "w": ["One half takes over every single task", "Both halves lose all old memories", "The whole brain stops working"], "why": "both"},
  {"a": "Different brain areas do different jobs", "id": "psychology_0030", "p": "What is localisation of function?", "s": "The Brain", "w": ["The whole brain shares every job equally", "Brain areas swap their jobs every day", "Only one area does all the thinking"], "why": "both"},
  {"a": "Damage to a small area of tissue", "id": "psychology_0031", "p": "In brain research, what is a lesion?", "s": "The Brain", "w": ["A picture of blood flow in the brain", "A burst of activity in one area", "A gap between two nerve cells"], "why": "both"},
  {"a": "The frontal lobe", "id": "psychology_0032", "p": "Damage to which lobe most changes self-control?", "s": "The Brain", "w": ["The occipital lobe", "The temporal lobe", "The parietal lobe"], "why": "attribution"},
  {"a": "Personality and self-control", "id": "psychology_0033", "p": "Frontal lobe damage most often changes what?", "s": "The Brain", "w": ["Hearing and understanding speech", "Balance and coordination", "Colour vision and depth"], "why": "both"},
  {"a": "Pleasure and motivation", "id": "psychology_0034", "p": "What is the brain's reward pathway linked to?", "s": "The Brain", "w": ["Balance and coordination", "Breathing and heart rate", "Language and grammar"], "why": "implausible-distractors"},
  {"a": "Glucose", "id": "psychology_0035", "p": "What does the brain use as its main fuel?", "s": "The Brain", "w": ["Calcium", "Protein", "Vitamin C"], "why": "implausible-distractors"},
  {"a": "The two halves take on different tasks", "id": "psychology_0037", "p": "What does lateralisation mean?", "s": "The Brain", "w": ["The two halves do exactly the same work", "The brain grows a new half in childhood", "Nerve signals cross over in the neck"], "why": "both"},
