  {"a": "A missing limb still feels present", "id": "psychology_0044", "p": "What happens in a phantom limb experience?", "s": "The Brain", "w": ["A limb looks larger than it really is", "A healthy limb feels completely numb", "A limb moves without any command"], "why": "both"},
  {"a": "Making new long-term memories", "id": "psychology_0045", "p": "The hippocampus is needed for what?", "s": "The Brain", "w": ["Turning sounds into understood words", "Keeping the body upright and steady", "Recalling memories from childhood"], "why": "both"},
  {"a": "Removing connections that go unused", "id": "psychology_0046", "p": "What is pruning in the developing brain?", "s": "The Brain", "w": ["Coating nerve fibres to speed signals", "Adding new connections between cells", "Replacing cells that have worn out"], "why": "both"},
