  {"a": "The nerves outside the brain and cord", "id": "psychology_0048", "p": "What is the peripheral nervous system?", "s": "The Brain", "w": ["The brain and the spinal cord together", "The glands that release hormones", "The nerve cells inside the cortex"], "why": "both"},
  {"a": "Take in messages from other cells", "id": "psychology_0050", "p": "What do dendrites do?", "s": "Neurons and Brain Chemicals", "w": ["Speed up the signal along a fibre", "Send messages out to other cells", "Release chemicals into the gap"], "why": "both"},
  {"a": "The fibre that carries a signal out", "id": "psychology_0051", "p": "What is an axon?", "s": "Neurons and Brain Chemicals", "w": ["The covering that speeds a signal up", "The branches that take signals in", "The gap between two nerve cells"], "why": "both"},
  {"a": "Speeds the signal along a fibre", "id": "psychology_0052", "p": "What does the myelin sheath do?", "s": "Neurons and Brain Chemicals", "w": ["Stores the chemicals a cell releases", "Takes in signals from other cells", "Carries the signal across a gap"], "why": "both"},
