  {"a": "Calming nerve cell activity", "id": "psychology_0059", "p": "What is GABA's main effect in the brain?", "s": "Neurons and Brain Chemicals", "w": ["Coating fibres to speed signals", "Exciting nerve cell activity", "Carrying oxygen to neurons"], "why": "implausible-distractors"},
  {"a": "Prepares the body for action", "id": "psychology_0062", "p": "What does adrenaline do?", "s": "Neurons and Brain Chemicals", "w": ["Signals that the stomach is full", "Starts the release of melatonin", "Calms the body after a scare"], "why": "both"},
