  {"a": "Boosts the effect of a brain chemical", "id": "psychology_0066", "p": "What does an agonist drug do?", "s": "Neurons and Brain Chemicals", "w": ["Blocks the effect of a brain chemical", "Slows how fast a signal travels", "Copies the shape of a hormone"], "why": "both"},
  {"a": "Blocks the effect of a brain chemical", "id": "psychology_0067", "p": "What does an antagonist drug do?", "s": "Neurons and Brain Chemicals", "w": ["Boosts the effect of a brain chemical", "Repairs nerve fibres that are damaged", "Speeds up the release of a hormone"], "why": "both"},
