  {"a": "Bonding and trust", "id": "psychology_0078", "p": "What is oxytocin often linked to?", "s": "Neurons and Brain Chemicals", "w": ["Sleep and the body clock", "Hunger and fullness", "Alertness and focus"], "why": "both"},
  {"a": "A short time when it cannot fire", "id": "psychology_0079", "p": "What is a refractory period for a neuron?", "s": "Neurons and Brain Chemicals", "w": ["The gap it must send a signal across", "A short time when it fires faster", "The charge it holds while resting"], "why": "both"},
  {"a": "The growth of new nerve cells", "id": "psychology_0080", "p": "What does neurogenesis mean?", "s": "Neurons and Brain Chemicals", "w": ["The coating of nerve fibres in fat", "The change in strength of a synapse", "The death of unused nerve cells"], "why": "both"},
  {"a": "Taking in signals from the senses", "id": "psychology_0081", "p": "What is sensation?", "s": "Sensation and Perception", "w": ["Making sense of signals from the senses", "Storing signals for later recall", "Turning signals into a decision"], "why": "both"},
