  {"a": "The layer at the back of the eye", "id": "psychology_0083", "p": "What is the retina?", "s": "Sensation and Perception", "w": ["The nerve that carries sight to the brain", "The clear window at the front of the eye", "The muscle that changes the pupil size"], "why": "both"},
  {"a": "Seeing in dim light", "id": "psychology_0084", "p": "What are rods in the eye for?", "s": "Sensation and Perception", "w": ["Judging distance with two eyes", "Seeing colour and fine detail", "Focusing light on the retina"], "why": "implausible-distractors"},
