  {"a": "The part of the inner ear that hears", "id": "psychology_0087", "p": "What is the cochlea?", "s": "Sensation and Perception", "w": ["The three small bones of the middle ear", "The thin skin that vibrates with sound", "The tube that balances air pressure"], "why": "both"},
  {"a": "Vibrates when sound waves hit it", "id": "psychology_0088", "p": "What does the eardrum do?", "s": "Sensation and Perception", "w": ["Keeps the head balanced when moving", "Turns vibration into nerve signals", "Passes vibration to the inner ear"], "why": "both"},
  {"a": "Changes size to control the light", "id": "psychology_0089", "p": "What does the pupil do?", "s": "Sensation and Perception", "w": ["Bends the light to focus an image", "Moves the eye to follow an object", "Turns light into nerve signals"], "why": "both"},
  {"a": "Focusing light onto the retina", "id": "psychology_0090", "p": "What is the lens of the eye for?", "s": "Sensation and Perception", "w": ["Controlling how much light enters", "Turning light into nerve signals", "Protecting the front of the eye"], "why": "both"},
  {"a": "Cones that do not work normally", "id": "psychology_0091", "p": "What usually causes colour blindness?", "s": "Sensation and Perception", "w": ["Rods that are missing from the eye", "A weak muscle around the pupil", "Damage to the lens of the eye"], "why": "both"},
  {"a": "The smallest signal you can detect", "id": "psychology_0092", "p": "What is the absolute threshold?", "s": "Sensation and Perception", "w": ["The smallest change you can notice", "The strongest signal you can bear", "The time taken to notice a signal"], "why": "both"},
  {"a": "The smallest change you can notice", "id": "psychology_0093", "p": "What is a just noticeable difference?", "s": "Sensation and Perception", "w": ["The smallest signal you can detect", "The largest change you can notice", "The time a signal stays in mind"], "why": "both"},
  {"a": "Noticing a steady signal less over time", "id": "psychology_0094", "p": "What is sensory adaptation?", "s": "Sensation and Perception", "w": ["Getting better at a skill with practice", "Noticing a new signal more over time", "Losing a sense after an injury"], "why": "both"},
  {"a": "No longer noticing a smell in a room", "id": "psychology_0095", "p": "Which is an example of sensory adaptation?", "s": "Sensation and Perception", "w": ["Suddenly hearing your name in a crowd", "Failing to see an obvious change", "Seeing movement in still lights"], "why": "both"},
  {"a": "Focusing on one thing, ignoring others", "id": "psychology_0096", "p": "What is selective attention?", "s": "Sensation and Perception", "w": ["Splitting attention evenly between things", "Reacting less to a signal that repeats", "Missing a change right in front of you"], "why": "both"},
  {"a": "Noticing your own name in a noisy room", "id": "psychology_0097", "p": "What is the cocktail party effect?", "s": "Sensation and Perception", "w": ["Following two conversations at once", "Losing track of every conversation", "Forgetting names you have just heard"], "why": "both"},
  {"a": "Missing something obvious while focused", "id": "psychology_0098", "p": "What is inattentional blindness?", "s": "Sensation and Perception", "w": ["Failing to notice that a scene changed", "Losing sight in one eye over time", "Seeing things that are not there"], "why": "both"},
  {"a": "Not noticing that something changed", "id": "psychology_0099", "p": "What is change blindness?", "s": "Sensation and Perception", "w": ["Not noticing an obvious thing in view", "Disliking any change in routine", "Losing colour vision slowly"], "why": "both"},
  {"a": "How we group parts into a whole", "id": "psychology_0100", "p": "What are Gestalt principles about?", "s": "Sensation and Perception", "w": ["How the eye turns light into signals", "How we judge distance with two eyes", "How a sense fades when it repeats"], "why": "both"},
  {"a": "Seeing an object apart from its background", "id": "psychology_0101", "p": "What does figure-ground mean?", "s": "Sensation and Perception", "w": ["Grouping objects that are close together", "Seeing an object as the same size", "Filling in the gaps of a shape"], "why": "both"},
  {"a": "Filling in gaps to see a whole shape", "id": "psychology_0102", "p": "What is closure in perception?", "s": "Sensation and Perception", "w": ["Seeing a shape apart from its background", "Judging a shape's distance from you", "Grouping shapes that look alike"], "why": "both"},
  {"a": "Grouping things that are close together", "id": "psychology_0103", "p": "What is proximity in perception?", "s": "Sensation and Perception", "w": ["Grouping things that look alike", "Grouping things that move in the same way", "Grouping things of the same size"], "why": "both"},
  {"a": "Grouping things that look alike", "id": "psychology_0104", "p": "What is similarity in perception?", "s": "Sensation and Perception", "w": ["Grouping things that are close together", "Filling in a gap to complete a shape", "Grouping things that move as one"], "why": "both"},
  {"a": "Signals that help you judge distance", "id": "psychology_0105", "p": "What are depth cues?", "s": "Sensation and Perception", "w": ["Signals that tell one colour from another", "Signals that help you group shapes", "Signals that warn of a loud sound"], "why": "both"},
  {"a": "Using two eyes together to judge depth", "id": "psychology_0106", "p": "What is binocular vision?", "s": "Sensation and Perception", "w": ["Using memory to judge an object's size", "Using one eye to judge depth by size", "Using the ears to locate a sound"], "why": "both"},
  {"a": "The difference between the two eye images", "id": "psychology_0107", "p": "What is retinal disparity?", "s": "Sensation and Perception", "w": ["The point where the nerve leaves the eye", "The blurring of an image far away", "The loss of colour in dim light"], "why": "both"},
  {"a": "Parallel lines seem to meet far away", "id": "psychology_0108", "p": "What is linear perspective?", "s": "Sensation and Perception", "w": ["Objects look the same size as they move", "Nearer objects block farther objects", "Distant objects look hazy and pale"], "why": "both"},
  {"a": "A nearer object blocks a farther one", "id": "psychology_0109", "p": "How does overlap help you judge distance?", "s": "Sensation and Perception", "w": ["Each eye receives a slightly different view", "A farther object looks paler and hazier", "Parallel lines seem to meet far away"], "why": "both"},
  {"a": "An object seems the same size as it moves", "id": "psychology_0110", "p": "What is size constancy?", "s": "Sensation and Perception", "w": ["An object seems to shrink as it moves away", "An object seems to move when it is still", "An object seems to change its colour"], "why": "both"},
  {"a": "A readiness to see things a certain way", "id": "psychology_0111", "p": "What is a perceptual set?", "s": "Sensation and Perception", "w": ["A habit of ignoring familiar sights", "A group of senses working together", "A limit on how much you can notice"], "why": "both"},
  {"a": "Using what you know to read a signal", "id": "psychology_0112", "p": "What is top-down processing?", "s": "Sensation and Perception", "w": ["Ignoring a signal that stays the same", "Building a picture from raw signals", "Grouping nearby parts into a whole"], "why": "both"},
  {"a": "Building a picture from raw signals", "id": "psychology_0113", "p": "What is bottom-up processing?", "s": "Sensation and Perception", "w": ["Using what you already know to guess", "Judging distance from two eye views", "Filling a gap to complete a shape"], "why": "both"},
  {"a": "An image that tricks the eye and brain", "id": "psychology_0114", "p": "What is an optical illusion?", "s": "Sensation and Perception", "w": ["An image that fades as you stare at it", "An image seen only in very dim light", "An image stored for a few seconds"], "why": "both"},
  {"a": "Make them look different in length", "id": "psychology_0115", "p": "Arrow ends on two equal lines can do what?", "s": "Sensation and Perception", "w": ["Make them look different in colour", "Make them seem to move slightly", "Make them appear to bend inward"], "why": "both"},
  {"a": "Still lights that seem to move", "id": "psychology_0116", "p": "What is the phi phenomenon?", "s": "Sensation and Perception", "w": ["Lights that seem to change colour", "Lights that seem to grow brighter", "Moving lights that seem still"], "why": "both"},
  {"a": "One sense triggering another sense", "id": "psychology_0117", "p": "What is synaesthesia?", "s": "Sensation and Perception", "w": ["One sense fading after an injury", "Two senses being blocked at once", "A sense growing stronger with age"], "why": "both"},
  {"a": "Sensing where your body parts are", "id": "psychology_0118", "p": "What is proprioception?", "s": "Sensation and Perception", "w": ["Sensing whether your head is upright", "Sensing warmth on your skin", "Sensing pain deep in the body"], "why": "both"},
  {"a": "The sense of balance", "id": "psychology_0119", "p": "What is the vestibular sense?", "s": "Sensation and Perception", "w": ["The sense of body position", "The sense of pain and heat", "The sense of smell"], "why": "both"},
  {"a": "Sensing body movement and position", "id": "psychology_0120", "p": "What is the kinaesthetic sense?", "s": "Sensation and Perception", "w": ["Sensing balance of the whole body", "Sensing pressure against the skin", "Sensing heat and cold"], "why": "both"},
  {"a": "Five", "id": "psychology_0121", "p": "How many basic tastes are usually listed?", "s": "Sensation and Perception", "w": ["Three", "Seven", "Four"], "why": "implausible-distractors"},
  {"a": "Savoury", "id": "psychology_0122", "p": "What kind of taste is umami?", "s": "Sensation and Perception", "w": ["Bitter", "Sweet", "Sour"], "why": "implausible-distractors"},
  {"a": "Much of flavour comes from smell", "id": "psychology_0123", "p": "Why does food taste bland with a blocked nose?", "s": "Sensation and Perception", "w": ["The tongue briefly loses its taste buds", "Saliva stops breaking food down", "The brain ignores weak signals"], "why": "both"},
  {"a": "It blocks some pain signals on the way up", "id": "psychology_0124", "p": "How can rubbing a sore spot ease the pain?", "s": "Sensation and Perception", "w": ["It sends the pain signals to the brain faster", "It releases extra pain chemicals", "It numbs the skin by cooling it"], "why": "both"},
  {"a": "What you hear them say", "id": "psychology_0125", "p": "Watching a speaker's lips can change what?", "s": "Sensation and Perception", "w": ["How fast you judge their speech", "How well you remember the words", "How loud you judge their voice"], "why": "attribution"},
  {"a": "Encoding, storage, and retrieval", "id": "psychology_0127", "p": "What are the three basic stages of memory?", "s": "Memory", "w": ["Attention, rehearsal, and forgetting", "Sensing, thinking, and deciding", "Input, rehearsal, and output"], "why": "both"},
  {"a": "Putting information into memory", "id": "psychology_0128", "p": "What is encoding?", "s": "Memory", "w": ["Taking information out of memory", "Holding information over time", "Losing information over time"], "why": "implausible-distractors"},
  {"a": "Getting information back out", "id": "psychology_0129", "p": "What is retrieval?", "s": "Memory", "w": ["Putting information in at the start", "Holding information over time", "Losing information over time"], "why": "both"},
  {"a": "A very brief record of the senses", "id": "psychology_0130", "p": "What is sensory memory?", "s": "Memory", "w": ["A store that can last a lifetime", "A store for skills and habits", "A store used while you work"], "why": "both"},
  {"a": "About 15 to 30 seconds", "id": "psychology_0131", "p": "Without rehearsal, how long does short-term memory last?", "s": "Memory", "w": ["About 5 to 10 minutes", "About 2 to 3 minutes", "About 1 to 2 seconds"], "why": "both"},
  {"a": "About seven", "id": "psychology_0132", "p": "How many items can short-term memory usually hold?", "s": "Memory", "w": ["About twenty", "About twelve", "About three"], "why": "implausible-distractors"},
  {"a": "The number of items, not their size", "id": "psychology_0133", "p": "What limits how much short-term memory holds?", "s": "Memory", "w": ["The size of the items, not the number", "How often you have seen them before", "The time of day you learn them"], "why": "both"},
  {"a": "Grouping items into larger units", "id": "psychology_0134", "p": "What is chunking?", "s": "Memory", "w": ["Linking items to places you picture", "Repeating items until they stick", "Testing yourself on items later"], "why": "both"},
  {"a": "Repeating information to hold it", "id": "psychology_0135", "p": "What is rehearsal in memory?", "s": "Memory", "w": ["Linking information to what you know", "Spreading study across many days", "Grouping information into units"], "why": "both"},
  {"a": "Holding and using information now", "id": "psychology_0136", "p": "What is working memory?", "s": "Memory", "w": ["Storing information for many years", "Taking in a signal for a second", "Recalling how to ride a bicycle"], "why": "both"},
  {"a": "Storage that can last for years", "id": "psychology_0137", "p": "What is long-term memory?", "s": "Memory", "w": ["Storage used while you solve a task", "Storage that lasts a few seconds", "Storage of the senses' raw input"], "why": "both"},
  {"a": "Memory you can describe in words", "id": "psychology_0138", "p": "What is explicit memory?", "s": "Memory", "w": ["Memory shown through skill and habit", "Memory that lasts only seconds", "Memory for how a place smelled"], "why": "both"},
  {"a": "Memory shown through skill and habit", "id": "psychology_0139", "p": "What is implicit memory?", "s": "Memory", "w": ["Memory for facts you learned at school", "Memory for events in your own life", "Memory you can describe in words"], "why": "both"},
  {"a": "Memory for how to do things", "id": "psychology_0140", "p": "What is procedural memory?", "s": "Memory", "w": ["Memory for events in your life", "Memory for facts and meanings", "Memory for a name and a face"], "why": "both"},
  {"a": "Memory for events in your own life", "id": "psychology_0141", "p": "What is episodic memory?", "s": "Memory", "w": ["Memory for general facts and words", "Memory for skills such as typing", "Memory held for a few seconds"], "why": "both"},
  {"a": "Memory for facts and meanings", "id": "psychology_0142", "p": "What is semantic memory?", "s": "Memory", "w": ["Memory for events in your own life", "Memory for skills and habits", "Memory for sounds just heard"], "why": "both"},
  {"a": "Memory drops fast, then levels off", "id": "psychology_0143", "p": "What does the forgetting curve show?", "s": "Memory", "w": ["Memory drops slowly, then all at once", "Memory improves steadily over time", "Memory stays perfect for a week"], "why": "both"},
  {"a": "Soon after learning it", "id": "psychology_0144", "p": "Most forgetting of new material happens when?", "s": "Memory", "w": ["Only after a night of sleep", "Evenly over many weeks", "Many months later"], "why": "both"},
  {"a": "Spread-out study beats cramming", "id": "psychology_0145", "p": "What is the spacing effect?", "s": "Memory", "w": ["Reading aloud beats reading quietly", "Cramming beats spread-out study", "Studying late at night works best"], "why": "both"},
  {"a": "Recalling the first and last items best", "id": "psychology_0146", "p": "What is the serial position effect?", "s": "Memory", "w": ["Recalling the middle items best of all", "Recalling long lists better than short", "Recalling items in a random order"], "why": "both"},
  {"a": "Recalling the earliest items best", "id": "psychology_0147", "p": "What is the primacy effect?", "s": "Memory", "w": ["Recalling the most recent items best", "Recalling items you found hardest", "Recalling the middle items best"], "why": "both"},
  {"a": "Recalling the most recent items best", "id": "psychology_0148", "p": "What is the recency effect?", "s": "Memory", "w": ["Recalling the middle items best of all", "Recalling the earliest items best", "Recalling the shortest items best"], "why": "both"},
  {"a": "Recalling better in the same mood", "id": "psychology_0149", "p": "What is state-dependent memory?", "s": "Memory", "w": ["Recalling better in the same place", "Recalling better after a long rest", "Recalling better at the same hour"], "why": "both"},
  {"a": "Recalling better in the same place", "id": "psychology_0150", "p": "What is context-dependent memory?", "s": "Memory", "w": ["Recalling better with a written list", "Recalling better while standing up", "Recalling better in the same mood"], "why": "both"},
  {"a": "A hint that brings back a memory", "id": "psychology_0151", "p": "What is a retrieval cue?", "s": "Memory", "w": ["A method for storing a memory", "A test of how much you recall", "A reason a memory is lost"], "why": "both"},
  {"a": "Identifying something met before", "id": "psychology_0152", "p": "What is recognition?", "s": "Memory", "w": ["Learning something for the first time", "Forgetting something you once knew", "Recalling something with no hints"], "why": "both"},
  {"a": "Bringing it to mind without hints", "id": "psychology_0153", "p": "What is recall?", "s": "Memory", "w": ["Picking it out from a list of options", "Reading it aloud from a written note", "Grouping it with similar items"], "why": "both"},
  {"a": "Other memories getting in the way", "id": "psychology_0154", "p": "What is interference in memory?", "s": "Memory", "w": ["A memory simply fading with time alone", "A memory changed by later news", "A memory blocked by tiredness"], "why": "both"},
  {"a": "Old learning disturbs new learning", "id": "psychology_0155", "p": "What is proactive interference?", "s": "Memory", "w": ["New learning disturbs old learning", "Sleep disturbs recent learning", "Stress disturbs all learning"], "why": "implausible-distractors"},
  {"a": "New learning disturbs old learning", "id": "psychology_0156", "p": "What is retroactive interference?", "s": "Memory", "w": ["Noise disturbs learning as it happens", "Old learning disturbs new learning", "Illness disturbs stored memories"], "why": "both"},
  {"a": "Knowing a word but not finding it", "id": "psychology_0157", "p": "What is the tip-of-the-tongue feeling?", "s": "Memory", "w": ["Saying a completely wrong word by mistake", "Forgetting a word you never knew", "Hearing a word you cannot place"], "why": "both"},
  {"a": "A vivid memory of a shocking event", "id": "psychology_0158", "p": "What is a flashbulb memory?", "s": "Memory", "w": ["A memory built from other people's words", "A memory of a skill such as typing", "A memory that lasts only a second"], "why": "both"},
  {"a": "Later wrong details change a memory", "id": "psychology_0159", "p": "What is the misinformation effect?", "s": "Memory", "w": ["A strong feeling makes a memory vivid", "A memory fades when it is not used", "Old learning blocks a new memory"], "why": "both"},
  {"a": "It adds details the person then recalls", "id": "psychology_0160", "p": "How can a leading question change a memory?", "s": "Memory", "w": ["It makes the memory last much longer", "It blocks the memory for a few days", "It removes the memory completely"], "why": "both"},
  {"a": "Memory can change after the event", "id": "psychology_0161", "p": "Why can eyewitness memory be unreliable?", "s": "Memory", "w": ["Memory is stored exactly as it was seen", "Memory works best under high stress", "Memory fades only in old age"], "why": "both"},
  {"a": "Losing memories from before an event", "id": "psychology_0163", "p": "What is retrograde amnesia?", "s": "Memory", "w": ["Being unable to form any new memories", "Losing memories only while asleep", "Losing only the memory of names"], "why": "both"},
  {"a": "Being unable to form new memories", "id": "psychology_0164", "p": "What is anterograde amnesia?", "s": "Memory", "w": ["Losing memories from before an event", "Losing the meaning of common words", "Losing memories of one language"], "why": "both"},
  {"a": "A trick that helps you remember", "id": "psychology_0165", "p": "What is a mnemonic?", "s": "Memory", "w": ["A test of how much you remember", "A cause of everyday forgetting", "A store that holds skills only"], "why": "both"},
  {"a": "Linking items to places you picture", "id": "psychology_0166", "p": "What is the method of loci?", "s": "Memory", "w": ["Repeating items over and over until they stick", "Grouping items into larger units", "Linking items to a rhyme you know"], "why": "both"},
  {"a": "Linking new material to what you know", "id": "psychology_0167", "p": "What is elaborative rehearsal?", "s": "Memory", "w": ["Repeating new material without thinking", "Reading new material very quickly", "Copying new material out by hand"], "why": "both"},
  {"a": "Thinking about the meaning", "id": "psychology_0168", "p": "Which kind of study creates the strongest memory?", "s": "Memory", "w": ["Repeating the words aloud", "Copying the words by hand", "Reading the words quickly"], "why": "both"},
  {"a": "Memories becoming more stable", "id": "psychology_0169", "p": "What is consolidation in memory?", "s": "Memory", "w": ["Memories blocked by a strong cue", "Memories fading within minutes", "Memories changed by later news"], "why": "both"},
  {"a": "Sleep", "id": "psychology_0170", "p": "Much memory consolidation happens during what?", "s": "Memory", "w": ["Exercise", "Reading", "Eating"], "why": "implausible-distractors"},
  {"a": "Being quizzed improves later recall", "id": "psychology_0171", "p": "What is the testing effect?", "s": "Memory", "w": ["Re-reading improves later recall more", "Testing measures ability, not memory", "Testing weakens a memory each time"], "why": "both"},
  {"a": "Recalling a fact but not its source", "id": "psychology_0172", "p": "What is source amnesia?", "s": "Memory", "w": ["Recalling an event that never happened", "Recalling a source but not the fact", "Losing all memory of one event"], "why": "both"},
  {"a": "Learning to link two signals together", "id": "psychology_0173", "p": "What is classical conditioning?", "s": "Learning and Conditioning", "w": ["Learning from rewards and consequences", "Learning by watching another person", "Learning that shows up only later"], "why": "both"},
  {"a": "A link between two signals", "id": "psychology_0174", "p": "In classical conditioning, what is learned?", "s": "Learning and Conditioning", "w": ["A link between an act and a reward", "A rule copied from another person", "A skill built by slow practice"], "why": "attribution"},
  {"a": "Something that triggers a natural reaction", "id": "psychology_0175", "p": "What is an unconditioned stimulus?", "s": "Learning and Conditioning", "w": ["Something that triggers a learned reaction", "Something that follows a good action", "Something that ends a learned link"], "why": "both"},
  {"a": "A signal that gains meaning through learning", "id": "psychology_0176", "p": "What is a conditioned stimulus?", "s": "Learning and Conditioning", "w": ["A signal that already carries meaning from birth", "A reaction that needs no learning", "A reward given after a behaviour"], "why": "both"},
  {"a": "A reaction that was never learned", "id": "psychology_0177", "p": "What is an unconditioned response?", "s": "Learning and Conditioning", "w": ["A reaction built up through learning", "A reward that follows a behaviour", "A signal that predicts a reward"], "why": "both"},
  {"a": "A reaction that has been learned", "id": "psychology_0178", "p": "What is a conditioned response?", "s": "Learning and Conditioning", "w": ["A reward that strengthens an act", "A reaction present from birth", "A signal given before an event"], "why": "both"},
  {"a": "A learned response fades when the link stops", "id": "psychology_0179", "p": "What is extinction in conditioning?", "s": "Learning and Conditioning", "w": ["A learned response returns after a rest", "A learned response spreads to new signals", "A learned response grows with each reward"], "why": "both"},
  {"a": "A faded response returns after a rest", "id": "psychology_0180", "p": "What is spontaneous recovery?", "s": "Learning and Conditioning", "w": ["A response appears without any learning", "A response spreads to similar signals", "A response fades when rewards stop"], "why": "both"},
  {"a": "Responding to similar signals too", "id": "psychology_0181", "p": "What is generalisation in conditioning?", "s": "Learning and Conditioning", "w": ["Learning to tell similar signals apart", "Responding less each time it repeats", "Responding only after a long delay"], "why": "both"},
  {"a": "Learning to tell similar signals apart", "id": "psychology_0182", "p": "What is discrimination in conditioning?", "s": "Learning and Conditioning", "w": ["Responding to similar signals too", "Treating every signal as a reward", "Losing a response when rewards stop"], "why": "both"},
  {"a": "Yes, by pairing it with a scare", "id": "psychology_0183", "p": "Can a fear of an object be learned?", "s": "Learning and Conditioning", "w": ["No, fears are present from birth", "No, fears come only from real harm", "Yes, but only in adults"], "why": "attribution"},
  {"a": "Learning from rewards and consequences", "id": "psychology_0184", "p": "What is operant conditioning?", "s": "Learning and Conditioning", "w": ["Learning that stays hidden for a time", "Learning to link two signals together", "Learning by copying another person"], "why": "both"},
  {"a": "What happens after the behaviour", "id": "psychology_0185", "p": "In operant conditioning, what changes behaviour?", "s": "Learning and Conditioning", "w": ["What signal comes before it", "How often the signal repeats", "How long the behaviour lasts"], "why": "attribution"},
  {"a": "Adding something good to increase an act", "id": "psychology_0186", "p": "What is positive reinforcement?", "s": "Learning and Conditioning", "w": ["Taking away something bad to increase an act", "Taking away something good to reduce an act", "Adding something bad to reduce an act"], "why": "both"},
  {"a": "Taking away something bad to increase an act", "id": "psychology_0187", "p": "What is negative reinforcement?", "s": "Learning and Conditioning", "w": ["Taking away something good to reduce an act", "Adding something good to increase an act", "Adding something bad to reduce an act"], "why": "both"},
  {"a": "A result that makes an act less likely", "id": "psychology_0188", "p": "What is punishment in learning?", "s": "Learning and Conditioning", "w": ["A result that makes an act more likely", "A signal given before an act starts", "A reward held back until the end"], "why": "both"},
  {"a": "Something rewarding from birth", "id": "psychology_0189", "p": "What is a primary reinforcer?", "s": "Learning and Conditioning", "w": ["Something learned to be rewarding", "Something that ends a behaviour", "Something that signals a reward"], "why": "implausible-distractors"},
  {"a": "Something learned to be rewarding", "id": "psychology_0190", "p": "What is a secondary reinforcer?", "s": "Learning and Conditioning", "w": ["Something that warns of punishment", "Something rewarding from birth", "Something that stops a behaviour"], "why": "both"},
  {"a": "Rewarding small steps toward a goal", "id": "psychology_0191", "p": "What is shaping?", "s": "Learning and Conditioning", "w": ["Rewarding only the finished skill", "Removing a reward to end an act", "Copying the steps of an expert"], "why": "both"},
  {"a": "Rewarding the act every single time", "id": "psychology_0192", "p": "What is continuous reinforcement?", "s": "Learning and Conditioning", "w": ["Rewarding the act after a set number of tries", "Rewarding the act now and then", "Rewarding the act only at the end"], "why": "both"},
  {"a": "Rewarding the act only some of the time", "id": "psychology_0193", "p": "What is partial reinforcement?", "s": "Learning and Conditioning", "w": ["Giving no result after the act at all", "Rewarding the act every single time", "Punishing the act every single time"], "why": "both"},
  {"a": "Unpredictable rewards", "id": "psychology_0194", "p": "Which kind of reward makes a habit hardest to break?", "s": "Learning and Conditioning", "w": ["Rewards every single time", "Rewards after a set time", "Rewards only at the end"], "why": "implausible-distractors"},
  {"a": "A reward after a set amount of time", "id": "psychology_0195", "p": "What is a fixed-interval schedule?", "s": "Learning and Conditioning", "w": ["A reward after a random number of acts", "A reward after a random length of time", "A reward after a set number of acts"], "why": "implausible-distractors"},
  {"a": "A reward after a random number of tries", "id": "psychology_0196", "p": "What is a variable-ratio schedule?", "s": "Learning and Conditioning", "w": ["A reward after a random length of time", "A reward after a set number of tries", "A reward after a set length of time"], "why": "both"},
  {"a": "They reward players unpredictably", "id": "psychology_0197", "p": "Why are slot machines so hard to stop playing?", "s": "Learning and Conditioning", "w": ["They punish players who stop early", "They reward players on every try", "They reward players once an hour"], "why": "both"},
  {"a": "Learning by watching other people", "id": "psychology_0198", "p": "What is observational learning?", "s": "Learning and Conditioning", "w": ["Learning from rewards and results", "Learning by trial and error alone", "Learning by linking two signals"], "why": "both"},
  {"a": "Copy the rough behaviour", "id": "psychology_0199", "p": "Children who watch an adult act roughly often do what?", "s": "Learning and Conditioning", "w": ["Play more quietly than before", "Avoid the adult afterwards", "Forget what they have seen"], "why": "attribution"},
  {"a": "New behaviour, including aggression", "id": "psychology_0200", "p": "What can children learn just by watching?", "s": "Learning and Conditioning", "w": ["Only behaviour that is rewarded", "Nothing until they try it once", "Only behaviour they are taught"], "why": "both"},
  {"a": "Copying the behaviour of another person", "id": "psychology_0201", "p": "What is modelling in psychology?", "s": "Learning and Conditioning", "w": ["Removing a reward to end a behaviour", "Rewarding a behaviour step by step", "Pairing a behaviour with a signal"], "why": "both"},
  {"a": "Learning that shows only when needed", "id": "psychology_0202", "p": "What is latent learning?", "s": "Learning and Conditioning", "w": ["Learning that happens in a single instant", "Learning that fades without reward", "Learning that comes from copying"], "why": "both"},
  {"a": "A mental picture of a place", "id": "psychology_0203", "p": "What is a cognitive map?", "s": "Learning and Conditioning", "w": ["A plan for solving a problem", "A record of rewards received", "A list of steps to a goal"], "why": "both"},
  {"a": "Giving up after events you cannot control", "id": "psychology_0204", "p": "What is learned helplessness?", "s": "Learning and Conditioning", "w": ["Believing your own effort always works", "Trying harder after a run of failures", "Asking for help before trying alone"], "why": "both"},
  {"a": "Giving up even when escape is possible", "id": "psychology_0205", "p": "Repeated uncontrollable events can lead to what?", "s": "Learning and Conditioning", "w": ["Trying twice as hard the next time", "Forgetting the events completely", "Learning the task much faster"], "why": "attribution"},
  {"a": "Reacting less to a repeated signal", "id": "psychology_0206", "p": "What is habituation?", "s": "Learning and Conditioning", "w": ["Reacting more to a repeated signal", "Learning to fear a harmless thing", "Linking a signal with a reward"], "why": "both"},
  {"a": "Avoiding a food that once made you ill", "id": "psychology_0207", "p": "What is taste aversion?", "s": "Learning and Conditioning", "w": ["Preferring a food after one very good meal", "Losing the sense of taste with age", "Eating only foods you know well"], "why": "both"},
  {"a": "A reward lowers interest in a loved task", "id": "psychology_0208", "p": "What is the overjustification effect?", "s": "Learning and Conditioning", "w": ["A reward raises interest in a dull task", "A punishment improves a learned skill", "Practice makes a task feel easier"], "why": "both"},
  {"a": "Doing something because you enjoy it", "id": "psychology_0209", "p": "What is intrinsic motivation?", "s": "Learning and Conditioning", "w": ["Doing something to earn an outside reward", "Doing something to impress other people", "Doing something to avoid punishment"], "why": "both"},
  {"a": "Doing something for an outside reward", "id": "psychology_0210", "p": "What is extrinsic motivation?", "s": "Learning and Conditioning", "w": ["Doing something out of plain habit", "Doing something without any reason", "Doing something for the joy of it"], "why": "both"},
  {"a": "Earning tokens to trade for rewards", "id": "psychology_0211", "p": "What is a token economy?", "s": "Learning and Conditioning", "w": ["Paying a small fee for each session", "Learning to control body signals", "Facing a fear in very small steps"], "why": "both"},
  {"a": "Facing a fear slowly while relaxed", "id": "psychology_0212", "p": "What is systematic desensitisation?", "s": "Learning and Conditioning", "w": ["Pairing a habit with something nasty", "Talking through a fear's early cause", "Facing a fear fully and all at once"], "why": "both"},
  {"a": "With animals in a small chamber", "id": "psychology_0213", "p": "How are reward schedules usually tested?", "s": "Learning and Conditioning", "w": ["With people filling in a survey", "With children watching a video", "With patients during therapy"], "why": "both"},
  {"a": "Using body readings to learn control", "id": "psychology_0214", "p": "What is biofeedback?", "s": "Learning and Conditioning", "w": ["Using a reward to shape a behaviour", "Using relaxation to face a fear", "Using a diary to track a habit"], "why": "both"},
  {"a": "Noticing only the facts that fit your belief", "id": "psychology_0215", "p": "What is confirmation bias?", "s": "Thinking and Biases", "w": ["Judging risk by how easily cases come to mind", "Relying too much on the first number heard", "Feeling you knew the result all along"], "why": "both"},
  {"a": "Feeling you knew it all along afterwards", "id": "psychology_0216", "p": "What is hindsight bias?", "s": "Thinking and Biases", "w": ["Noticing only facts that fit your belief", "Judging by how well something fits a type", "Being more certain than you are correct"], "why": "both"},
  {"a": "Judging risk by how easily cases come to mind", "id": "psychology_0217", "p": "What is the availability heuristic?", "s": "Thinking and Biases", "w": ["Judging risk by counting every recorded case", "Judging by the first number you were given", "Judging by how well something fits a type"], "why": "both"},
  {"a": "Judging by how well something fits a type", "id": "psychology_0218", "p": "What is the representativeness heuristic?", "s": "Thinking and Biases", "w": ["Judging by the first number you were given", "Judging by how common the type really is", "Judging by how easily cases come to mind"], "why": "both"},
  {"a": "Relying too much on the first number heard", "id": "psychology_0219", "p": "What is anchoring?", "s": "Thinking and Biases", "w": ["Relying too much on the last number heard", "Relying on the most detailed story given", "Relying on how easily examples come up"], "why": "both"},
  {"a": "The wording of a choice changes your answer", "id": "psychology_0220", "p": "What is the framing effect?", "s": "Thinking and Biases", "w": ["The order of the choices changes your answer", "The number of choices changes your answer", "The first figure given changes your answer"], "why": "both"},
  {"a": "A loss hurts more than an equal gain pleases", "id": "psychology_0221", "p": "What is loss aversion?", "s": "Thinking and Biases", "w": ["A gain pleases more than an equal loss hurts", "A loss feels smaller once you own the item", "A loss and a gain feel exactly the same"], "why": "both"},
  {"a": "Carrying on because of what you already spent", "id": "psychology_0222", "p": "What is the sunk cost fallacy?", "s": "Thinking and Biases", "w": ["Stopping as soon as the costs begin to rise", "Preferring things to stay just as they are", "Valuing a thing more once you own it"], "why": "both"},
  {"a": "Thinking past chance results change the next", "id": "psychology_0223", "p": "What is the gambler's fallacy?", "s": "Thinking and Biases", "w": ["Thinking extreme results move back to average", "Thinking you can influence a random event", "Thinking a detailed story is more likely"], "why": "both"},
  {"a": "Thinking bad things are less likely for you", "id": "psychology_0224", "p": "What is optimism bias?", "s": "Thinking and Biases", "w": ["Thinking good things are less likely for you", "Thinking others notice you more than they do", "Thinking most people agree with your view"], "why": "both"},
  {"a": "Beginners overrating their own skill", "id": "psychology_0225", "p": "What is the Dunning-Kruger effect?", "s": "Thinking and Biases", "w": ["Everyone judging their skill correctly", "Experts overrating their own skill", "Beginners avoiding any new skill"], "why": "implausible-distractors"},
  {"a": "One good quality colours your whole opinion", "id": "psychology_0226", "p": "What is the halo effect?", "s": "Thinking and Biases", "w": ["One number anchors every later judgement", "One bad event outweighs many good ones", "One vague description seems to fit you"], "why": "both"},
  {"a": "Blaming the person, not their situation", "id": "psychology_0227", "p": "What is the fundamental attribution error?", "s": "Thinking and Biases", "w": ["Blaming the situation and not the person", "Taking credit but passing on the blame", "Assuming your view is the common one"], "why": "both"},
  {"a": "Taking credit but passing blame to others", "id": "psychology_0228", "p": "What is self-serving bias?", "s": "Thinking and Biases", "w": ["Taking blame but passing credit to others", "Blaming a person rather than a situation", "Assuming other people share your views"], "why": "both"},
  {"a": "Assuming most people agree with you", "id": "psychology_0229", "p": "What is the false consensus effect?", "s": "Thinking and Biases", "w": ["Assuming most people disagree with you", "Assuming others notice your feelings", "Assuming a group is all the same"], "why": "both"},
  {"a": "Believing a thing because many others do", "id": "psychology_0230", "p": "What is the bandwagon effect?", "s": "Thinking and Biases", "w": ["Believing a thing because an expert said it", "Believing a thing that fits what you hope", "Believing a thing after hearing it often"], "why": "both"},
  {"a": "Liking something more after seeing it often", "id": "psychology_0231", "p": "What is the mere exposure effect?", "s": "Thinking and Biases", "w": ["Liking something less after seeing it often", "Noticing something less after it repeats", "Wanting something more once it is scarce"], "why": "both"},
  {"a": "Bad news affects you more than good news", "id": "psychology_0232", "p": "What is negativity bias?", "s": "Thinking and Biases", "w": ["Recent news affects you more than old news", "Vague news feels more personal than facts", "Good news affects you more than bad news"], "why": "both"},
  {"a": "Holding a belief after it is disproved", "id": "psychology_0233", "p": "What is belief perseverance?", "s": "Thinking and Biases", "w": ["Changing a belief as soon as it is tested", "Holding two beliefs that clash at once", "Noticing only what supports a belief"], "why": "both"},
  {"a": "Believing you can steer a random event", "id": "psychology_0234", "p": "What is the illusion of control?", "s": "Thinking and Biases", "w": ["Believing your group is better than others", "Believing others can read your feelings", "Believing you knew the answer all along"], "why": "both"},
  {"a": "Feeling better because you expect to", "id": "psychology_0235", "p": "What is the placebo effect?", "s": "Thinking and Biases", "w": ["Feeling nothing from a real treatment", "Feeling worse because you expect to", "Feeling better after a long rest"], "why": "both"},
  {"a": "A vague description seems to fit you", "id": "psychology_0236", "p": "What is the Barnum effect?", "s": "Thinking and Biases", "w": ["A confident speaker seems more right", "A detailed story seems more likely", "A repeated claim seems more true"], "why": "both"},
  {"a": "Thinking others notice you more than they do", "id": "psychology_0237", "p": "What is the spotlight effect?", "s": "Thinking and Biases", "w": ["Thinking that others can read all your feelings", "Thinking others are all much the same", "Thinking others agree with your view"], "why": "both"},
  {"a": "Forgetting that others do not know it", "id": "psychology_0238", "p": "What is the curse of knowledge?", "s": "Thinking and Biases", "w": ["Forgetting something you knew last year", "Assuming others share your opinion", "Assuming an expert must be correct"], "why": "both"},
  {"a": "Seeing only the usual use for an object", "id": "psychology_0239", "p": "What is functional fixedness?", "s": "Thinking and Biases", "w": ["Sticking to a method that worked before", "Seeing an object apart from its setting", "Narrowing many ideas down to one answer"], "why": "both"},
  {"a": "Sticking to a method that worked before", "id": "psychology_0240", "p": "What is a mental set?", "s": "Thinking and Biases", "w": ["Seeing only the usual use for an object", "Setting a clear goal before starting", "Trying many new methods at once"], "why": "both"},
  {"a": "A step-by-step method that always works", "id": "psychology_0241", "p": "What is an algorithm in problem solving?", "s": "Thinking and Biases", "w": ["A guess that is checked against a rule", "A sudden idea that solves the problem", "A quick shortcut that usually works"], "why": "both"},
  {"a": "A quick mental shortcut", "id": "psychology_0242", "p": "What is a heuristic?", "s": "Thinking and Biases", "w": ["A slow but certain method", "A sudden flash of insight", "A fixed rule of logic"], "why": "implausible-distractors"},
  {"a": "Slower but more reliable", "id": "psychology_0243", "p": "Compared with a heuristic, an algorithm is usually what?", "s": "Thinking and Biases", "w": ["Faster but less reliable", "Faster and more reliable", "Slower and less reliable"], "why": "implausible-distractors"},
  {"a": "Narrowing many ideas down to one answer", "id": "psychology_0244", "p": "What is convergent thinking?", "s": "Thinking and Biases", "w": ["Producing many different possible ideas", "Sticking with a method that once worked", "Seeing only the usual use of a thing"], "why": "both"},
  {"a": "Producing many different possible ideas", "id": "psychology_0245", "p": "What is divergent thinking?", "s": "Thinking and Biases", "w": ["Narrowing many ideas down to one answer", "Following a fixed set of steps exactly", "Judging an idea before trying it out"], "why": "both"},
  {"a": "A sudden understanding of the answer", "id": "psychology_0246", "p": "What is insight in problem solving?", "s": "Thinking and Biases", "w": ["A method that always finds an answer", "A slow step-by-step working out", "A guess made without any thought"], "why": "both"},
  {"a": "The most typical example of a group", "id": "psychology_0247", "p": "What is a prototype in thinking?", "s": "Thinking and Biases", "w": ["A mental framework for organising ideas", "A rule for sorting things into groups", "A rare case that breaks the pattern"], "why": "both"},
  {"a": "A mental grouping of similar things", "id": "psychology_0248", "p": "What is a concept?", "s": "Thinking and Biases", "w": ["A framework that organises knowledge", "A best example of a whole group", "A step-by-step way to an answer"], "why": "both"},
  {"a": "A mental framework for organising ideas", "id": "psychology_0249", "p": "What is a schema?", "s": "Thinking and Biases", "w": ["A grouping of things that are alike", "A best example of a whole category", "A shortcut used to judge quickly"], "why": "both"},
  {"a": "Fitting new facts into an old idea", "id": "psychology_0250", "p": "What is assimilation in learning?", "s": "Thinking and Biases", "w": ["Rejecting facts that clash with belief", "Changing an old idea to fit new facts", "Storing new facts without any change"], "why": "both"},
  {"a": "Changing an old idea to fit new facts", "id": "psychology_0251", "p": "What is accommodation in learning?", "s": "Thinking and Biases", "w": ["Fitting new facts into an old idea", "Forgetting facts that no longer fit", "Keeping an idea whatever the facts"], "why": "both"},
  {"a": "Thinking about your own thinking", "id": "psychology_0252", "p": "What is metacognition?", "s": "Thinking and Biases", "w": ["Thinking about what other people want", "Thinking faster than usual", "Thinking without any words"], "why": "both"},
  {"a": "Being more certain than you are correct", "id": "psychology_0253", "p": "What is the overconfidence effect?", "s": "Thinking and Biases", "w": ["Being less certain than you are correct", "Being certain only about small things", "Being unable to make any decision"], "why": "both"},
  {"a": "Ignoring how common something really is", "id": "psychology_0254", "p": "What is base rate neglect?", "s": "Thinking and Biases", "w": ["Ignoring the details of a single case", "Ignoring the cost you already spent", "Ignoring advice from a real expert"], "why": "both"},
  {"a": "Thinking a detailed story is more likely", "id": "psychology_0255", "p": "What is the conjunction fallacy?", "s": "Thinking and Biases", "w": ["Thinking a simple event is more likely", "Thinking past luck changes the next go", "Thinking extremes will repeat exactly"], "why": "both"},
  {"a": "Makes it feel more likely, not less", "id": "psychology_0256", "p": "Adding detail to a story usually does what?", "s": "Thinking and Biases", "w": ["Makes it feel less likely, not more", "Makes it harder to judge the source", "Makes it easier to remember later"], "why": "both"},
  {"a": "A regular error in judgement", "id": "psychology_0257", "p": "What is a cognitive bias?", "s": "Thinking and Biases", "w": ["A gap in stored knowledge", "A failure of the senses", "A slow style of thinking"], "why": "both"},
  {"a": "Fast, automatic, and effortless", "id": "psychology_0258", "p": "What is System 1 thinking?", "s": "Thinking and Biases", "w": ["Slow, careful, and full of effort", "Fast, careful, and deliberate", "Slow, automatic, and silent"], "why": "both"},
  {"a": "Slow thinking that takes effort", "id": "psychology_0259", "p": "What is System 2 thinking?", "s": "Thinking and Biases", "w": ["Fast thinking that takes no effort", "Thinking that happens during sleep", "Thinking that uses pictures only"], "why": "both"},
  {"a": "Choosing worse after many decisions", "id": "psychology_0260", "p": "What is decision fatigue?", "s": "Thinking and Biases", "w": ["Choosing better after many decisions", "Choosing faster as the day goes on", "Choosing at random when tired out"], "why": "both"},
  {"a": "Too many options make choosing harder", "id": "psychology_0261", "p": "What is choice overload?", "s": "Thinking and Biases", "w": ["Too many options make choosing faster", "Too few options make choosing harder", "Too much detail makes a story likely"], "why": "both"},
  {"a": "Valuing a thing more once you own it", "id": "psychology_0262", "p": "What is the endowment effect?", "s": "Thinking and Biases", "w": ["Valuing a thing less once you own it", "Valuing a thing more once it is rare", "Valuing a thing by its first price"], "why": "both"},
  {"a": "Preferring things to stay as they are", "id": "psychology_0263", "p": "What is status quo bias?", "s": "Thinking and Biases", "w": ["Preferring any change to no change", "Preferring the option listed first", "Preferring what most others prefer"], "why": "both"},
  {"a": "Favouring the group you belong to", "id": "psychology_0264", "p": "What is in-group bias?", "s": "Thinking and Biases", "w": ["Seeing other groups as all alike", "Treating every group the same way", "Blaming one group for a problem"], "why": "both"},
  {"a": "Seeing other groups as all alike", "id": "psychology_0265", "p": "What is out-group homogeneity?", "s": "Thinking and Biases", "w": ["Seeing your own group as all alike", "Avoiding contact with other groups", "Favouring the group you belong to"], "why": "both"},
  {"a": "Applying a fixed idea to a whole group", "id": "psychology_0266", "p": "What is stereotyping?", "s": "Thinking and Biases", "w": ["Treating a group unfairly in practice", "Feeling dislike toward a whole group", "Judging each person on their own"], "why": "both"},
  {"a": "Believing people get what they deserve", "id": "psychology_0267", "p": "What is the just-world hypothesis?", "s": "Thinking and Biases", "w": ["Believing effort always brings reward", "Believing the world is purely random", "Believing courts always judge fairly"], "why": "both"},
  {"a": "Discomfort from two clashing ideas", "id": "psychology_0268", "p": "What is cognitive dissonance?", "s": "Thinking and Biases", "w": ["Confusion between two similar words", "Difficulty recalling a stored idea", "Comfort from two ideas that agree"], "why": "both"},
  {"a": "Uncomfortable", "id": "psychology_0269", "p": "Acting against your belief usually feels how?", "s": "Thinking and Biases", "w": ["Reassuring", "Unnoticed", "Pleasant"], "why": "attribution"},
  {"a": "By changing one of their beliefs", "id": "psychology_0270", "p": "How do people often reduce cognitive dissonance?", "s": "Thinking and Biases", "w": ["By adding a third clashing belief", "By forgetting how the clash began", "By repeating the clash every day"], "why": "both"},
  {"a": "Seeing a link that is not really there", "id": "psychology_0271", "p": "What is an illusory correlation?", "s": "Thinking and Biases", "w": ["Missing a link that is really there", "Explaining a link with one cause", "Measuring a link very precisely"], "why": "both"},
  {"a": "Extreme results move toward average next", "id": "psychology_0272", "p": "What is regression to the mean?", "s": "Thinking and Biases", "w": ["Extreme results repeat almost exactly", "Average results turn extreme in time", "Extreme results grow more extreme"], "why": "both"},
  {"a": "Underestimating how long a task will take", "id": "psychology_0273", "p": "What is the planning fallacy?", "s": "Thinking and Biases", "w": ["Overestimating how long a task will take", "Underestimating how much a task costs", "Planning in far too much detail"], "why": "both"},
  {"a": "Looking at successes and missing failures", "id": "psychology_0274", "p": "What is survivorship bias?", "s": "Thinking and Biases", "w": ["Looking at failures and missing successes", "Looking only at the most recent cases", "Looking at the loudest voices only"], "why": "both"},
  {"a": "The body's roughly 24-hour cycle", "id": "psychology_0275", "p": "What is a circadian rhythm?", "s": "Sleep and Dreams", "w": ["A cycle repeating every 90 minutes", "A burst of activity in light sleep", "A slow wave seen in deep sleep"], "why": "both"},
  {"a": "They go limp and cannot move", "id": "psychology_0280", "p": "What happens to most muscles during REM sleep?", "s": "Sleep and Dreams", "w": ["They grow stronger through the night", "They tense up and twitch strongly", "They work as they do while awake"], "why": "both"},
  {"a": "Short bursts of brain activity", "id": "psychology_0281", "p": "What are sleep spindles?", "s": "Sleep and Dreams", "w": ["Fast eye movements under the lids", "Sudden jerks as you fall asleep", "Slow waves seen in deep sleep"], "why": "both"},
  {"a": "About 90 minutes", "id": "psychology_0284", "p": "About how long is one full sleep cycle?", "s": "Sleep and Dreams", "w": ["About 20 minutes", "About 45 minutes", "About 4 hours"], "why": "implausible-distractors"},
  {"a": "Trouble falling or staying asleep", "id": "psychology_0285", "p": "What is insomnia?", "s": "Sleep and Dreams", "w": ["Breathing stopping during sleep", "Waking in fear with no memory", "Falling asleep suddenly by day"], "why": "both"},
  {"a": "Breathing stopping during sleep", "id": "psychology_0286", "p": "What is sleep apnoea?", "s": "Sleep and Dreams", "w": ["Trouble falling or staying asleep", "Walking about while still asleep", "Falling asleep suddenly by day"], "why": "both"},
  {"a": "Falling asleep suddenly by day", "id": "psychology_0287", "p": "What is narcolepsy?", "s": "Sleep and Dreams", "w": ["Trouble falling or staying asleep", "Breathing stopping during sleep", "Waking in fear with no memory"], "why": "both"},
  {"a": "Waking in fear with no memory of it", "id": "psychology_0288", "p": "What is a night terror?", "s": "Sleep and Dreams", "w": ["A frightening dream you recall well", "Talking clearly while still asleep", "Being unable to move on waking"], "why": "both"},
  {"a": "Extra REM sleep after losing some", "id": "psychology_0290", "p": "What is REM rebound?", "s": "Sleep and Dreams", "w": ["Waking suddenly from a vivid dream", "Losing the ability to dream at all", "Falling asleep faster than usual"], "why": "both"},
  {"a": "Sort and store the day's memories", "id": "psychology_0291", "p": "One theory says dreams help the brain do what?", "s": "Sleep and Dreams", "w": ["Rest every nerve cell completely", "Rebuild the muscles used by day", "Slow the heart to its lowest rate"], "why": "both"},
  {"a": "The story you actually remember", "id": "psychology_0292", "p": "What is the manifest content of a dream?", "s": "Sleep and Dreams", "w": ["The stage the dream happened in", "The hidden meaning underneath", "The time the dream lasted"], "why": "both"},
  {"a": "The hidden meaning behind it", "id": "psychology_0293", "p": "What is the latent content of a dream?", "s": "Sleep and Dreams", "w": ["The story you actually recall", "The feeling you wake up with", "The length of time it lasted"], "why": "both"},
  {"a": "The brain makes a story from random signals", "id": "psychology_0294", "p": "What does activation-synthesis say about dreams?", "s": "Sleep and Dreams", "w": ["The brain replays the day's events in order", "The brain hides a wish inside each dream", "The brain rests fully and makes nothing"], "why": "both"},
  {"a": "Strengthen and store it", "id": "psychology_0295", "p": "What does sleep help memory do?", "s": "Sleep and Dreams", "w": ["Sort out which parts to keep", "Erase the parts you dreamed of", "Slow down how fast you recall"], "why": "implausible-distractors"},
  {"a": "About 7 to 9 hours", "id": "psychology_0296", "p": "How much sleep do most adults need each night?", "s": "Sleep and Dreams", "w": ["About 10 to 12 hours", "About 4 to 5 hours", "About 2 to 3 hours"], "why": "implausible-distractors"},
  {"a": "Poor attention and low mood", "id": "psychology_0297", "p": "What is a common effect of losing sleep?", "s": "Sleep and Dreams", "w": ["Faster reactions and steadier hands", "Sharper attention and high mood", "Stronger memory for new facts"], "why": "both"},
  {"a": "The body clock no longer fits local time", "id": "psychology_0298", "p": "What causes jet lag?", "s": "Sleep and Dreams", "w": ["The body loses fluid on a long flight", "The body misses its usual meal times", "The body clock speeds up in dry air"], "why": "both"},
  {"a": "An odd feeling as you fall asleep", "id": "psychology_0299", "p": "What is a hypnagogic sensation?", "s": "Sleep and Dreams", "w": ["A memory that returns during sleep", "A vivid dream in the early morning", "A sudden fear on waking at night"], "why": "both"},
  {"a": "How people change across their lives", "id": "psychology_0301", "p": "What does developmental psychology study?", "s": "How People Develop", "w": ["How the senses turn into perception", "How groups influence one person", "How memory is stored and lost"], "why": "both"},
  {"a": "A fertilised egg", "id": "psychology_0302", "p": "What is a zygote?", "s": "How People Develop", "w": ["An unborn baby at six months", "A cell that becomes a neuron", "A newborn baby"], "why": "both"},
  {"a": "Things that can harm an unborn baby", "id": "psychology_0303", "p": "What are teratogens?", "s": "How People Develop", "w": ["Things that help an unborn baby grow", "Reflexes a newborn baby is born with", "Stages a child passes through early"], "why": "both"},
  {"a": "Turning toward a touch near the mouth", "id": "psychology_0304", "p": "What is the rooting reflex?", "s": "How People Develop", "w": ["Gripping a finger placed in the palm", "Stepping when held above a surface", "Spreading the arms when startled"], "why": "both"},
  {"a": "A soft cloth mother, not a wire one", "id": "psychology_0305", "p": "What do infant monkeys prefer to cling to?", "s": "How People Develop", "w": ["Another infant monkey their own age", "Whichever mother is nearer to them", "A wire mother that gives the milk"], "why": "both"},
  {"a": "By how they react to a brief parting", "id": "psychology_0306", "p": "How is a baby's attachment usually measured?", "s": "How People Develop", "w": ["By how much they weigh at one year", "By how long they sleep each night", "By how many words they can say"], "why": "attribution"},
  {"a": "The child trusts the carer to return", "id": "psychology_0307", "p": "What is secure attachment?", "s": "How People Develop", "w": ["The child avoids the carer on return", "The child clings and will not settle", "The child treats everyone the same"], "why": "both"},
  {"a": "Distress when a carer leaves", "id": "psychology_0308", "p": "What is separation anxiety?", "s": "How People Develop", "w": ["Distress at a new face nearby", "Distress in a very loud room", "Distress at being put to bed"], "why": "both"},
  {"a": "Knowing a hidden thing still exists", "id": "psychology_0309", "p": "What is object permanence?", "s": "How People Develop", "w": ["Knowing others hold their own views", "Knowing a name belongs to one thing", "Knowing an amount stays the same"], "why": "both"},
  {"a": "The sensorimotor stage", "id": "psychology_0310", "p": "In which stage does object permanence develop?", "s": "How People Develop", "w": ["The concrete operational stage", "The formal operational stage", "The preoperational stage"], "why": "implausible-distractors"},
  {"a": "Abstract and logical thinking", "id": "psychology_0311", "p": "Which thinking ability comes last in childhood?", "s": "How People Develop", "w": ["Knowing hidden objects still exist", "Seeing another person's viewpoint", "Knowing amounts stay the same"], "why": "both"},
  {"a": "Hard to see another person's view", "id": "psychology_0312", "p": "What is egocentrism in young children?", "s": "How People Develop", "w": ["Hard to share toys with another child", "Hard to remember a hidden object", "Hard to sit still for very long"], "why": "both"},
  {"a": "Amount stays the same when shape changes", "id": "psychology_0313", "p": "What is conservation in child development?", "s": "How People Develop", "w": ["Amount changes when the shape changes", "Objects can be sorted into classes", "A hidden object still exists nearby"], "why": "both"},
  {"a": "The concrete operational stage", "id": "psychology_0314", "p": "When do children usually master conservation?", "s": "How People Develop", "w": ["The formal operational stage", "The preoperational stage", "The sensorimotor stage"], "why": "both"},
  {"a": "Abstract and logical thinking", "id": "psychology_0315", "p": "What marks the formal operational stage?", "s": "How People Develop", "w": ["Grouping objects by their class", "Thinking about concrete objects", "Understanding hidden objects"], "why": "implausible-distractors"},
  {"a": "What a child can do with a little help", "id": "psychology_0316", "p": "What is the zone of proximal development?", "s": "How People Develop", "w": ["What a child can already do without help", "What a child will learn next year", "What a child has just forgotten"], "why": "both"},
  {"a": "Just beyond what they can do alone", "id": "psychology_0317", "p": "Children learn best when a task is how hard?", "s": "How People Develop", "w": ["Well beyond anything they can do", "Exactly what they can do alone", "Much easier than they can do"], "why": "attribution"},
  {"a": "Help that is slowly reduced", "id": "psychology_0318", "p": "What is scaffolding in learning?", "s": "How People Develop", "w": ["Help that stays exactly the same", "Help given only after a mistake", "Help that increases over time"], "why": "both"},
  {"a": "Knowing others have their own thoughts", "id": "psychology_0319", "p": "What is theory of mind?", "s": "How People Develop", "w": ["Knowing a hidden object still exists", "Knowing how memory works in general", "Knowing your own strengths well"], "why": "both"},
  {"a": "Fear of unfamiliar people in infancy", "id": "psychology_0320", "p": "What is stranger anxiety?", "s": "How People Develop", "w": ["Fear of being left behind by a carer", "Fear of loud or sudden noises", "Fear of new places and rooms"], "why": "both"},
  {"a": "Social challenges across the whole life", "id": "psychology_0321", "p": "What do psychosocial stages describe?", "s": "How People Develop", "w": ["Steps in learning by reward and result", "Physical growth of the body over time", "Stages of memory loss in later life"], "why": "both"},
  {"a": "Identity versus role confusion", "id": "psychology_0322", "p": "What is the main challenge of adolescence?", "s": "How People Develop", "w": ["Generativity versus stagnation", "Industry versus inferiority", "Trust versus mistrust"], "why": "both"},
  {"a": "Trust versus mistrust", "id": "psychology_0323", "p": "What is the first psychosocial challenge in infancy?", "s": "How People Develop", "w": ["Identity versus confusion", "Initiative versus guilt", "Autonomy versus shame"], "why": "attribution"},
  {"a": "Integrity versus despair", "id": "psychology_0324", "p": "What is the psychosocial challenge of old age?", "s": "How People Develop", "w": ["Generativity versus stagnation", "Intimacy versus isolation", "Trust versus mistrust"], "why": "attribution"},
  {"a": "Authoritarian", "id": "psychology_0326", "p": "Which parenting style is strict with little warmth?", "s": "How People Develop", "w": ["Authoritative", "Uninvolved", "Permissive"], "why": "implausible-distractors"},
  {"a": "Permissive", "id": "psychology_0327", "p": "Which parenting style sets very few rules?", "s": "How People Develop", "w": ["Authoritarian", "Authoritative", "Uninvolved"], "why": "implausible-distractors"},
  {"a": "When the body becomes able to reproduce", "id": "psychology_0328", "p": "What is puberty?", "s": "How People Develop", "w": ["When monthly cycles finally come to an end", "When the body stops growing taller", "When a child first starts school"], "why": "both"},
  {"a": "A time when learning comes most easily", "id": "psychology_0329", "p": "What is a critical period in development?", "s": "How People Develop", "w": ["A time when a child sleeps most deeply", "A time when growth is at its fastest", "A time when illness is most likely"], "why": "both"},
  {"a": "How people decide right from wrong", "id": "psychology_0330", "p": "What does moral reasoning describe?", "s": "How People Develop", "w": ["How people recall events from long ago", "How people form close bonds", "How people judge distances"], "why": "both"},
  {"a": "Rewards and punishments", "id": "psychology_0331", "p": "The earliest moral thinking focuses on what?", "s": "How People Develop", "w": ["Wider universal principles", "Rules and social approval", "Fairness between groups"], "why": "both"},
  {"a": "The end of monthly cycles in women", "id": "psychology_0332", "p": "What is menopause?", "s": "How People Develop", "w": ["The start of monthly cycles in girls", "The start of grey hair and wrinkles", "The end of growth in height"], "why": "both"},
  {"a": "Reasoning quickly about new problems", "id": "psychology_0333", "p": "What is fluid intelligence?", "s": "How People Develop", "w": ["Knowledge built up over many years", "Skill at reading other people", "Memory for faces and names"], "why": "both"},
  {"a": "Knowledge built up over many years", "id": "psychology_0334", "p": "What is crystallised intelligence?", "s": "How People Develop", "w": ["Speed at solving a brand new puzzle", "Skill at managing your own feelings", "Memory held for a few seconds only"], "why": "both"},
  {"a": "It often stays steady or grows", "id": "psychology_0335", "p": "What happens to crystallised intelligence with age?", "s": "How People Develop", "w": ["It disappears after middle age", "It usually falls off sharply", "It changes from year to year"], "why": "both"},
  {"a": "Following the same people for years", "id": "psychology_0336", "p": "What is a longitudinal study?", "s": "How People Develop", "w": ["Comparing different ages at one time", "Testing one person on one day", "Watching animals in the wild"], "why": "both"},
  {"a": "Comparing different ages at one time", "id": "psychology_0337", "p": "What is a cross-sectional study?", "s": "How People Develop", "w": ["Following the same people for years", "Studying one case in deep detail", "Repeating a study to check it"], "why": "both"},
  {"a": "How genes and setting each shape us", "id": "psychology_0338", "p": "What does the nature and nurture debate ask?", "s": "How People Develop", "w": ["Whether animals can really think at all", "Whether memory can be measured", "How the eye turns light to colour"], "why": "both"},
  {"a": "The body reacts, then you feel it", "id": "psychology_0339", "p": "Which comes first, the body's reaction or the feeling?", "s": "Emotion and Motivation", "w": ["Both happen at the very same moment", "The feeling needs no body reaction", "You feel it, then the body reacts"], "why": "both"},
  {"a": "Yes, the two can start together", "id": "psychology_0340", "p": "Can you feel fear before your heart speeds up?", "s": "Emotion and Motivation", "w": ["No, the feeling always comes last", "Yes, but only in a real emergency", "No, the heart always comes first"], "why": "both"},
  {"a": "Body arousal and a label for it", "id": "psychology_0341", "p": "What two things make up an emotion?", "s": "Emotion and Motivation", "w": ["A thought and a memory of it", "A body change and a movement", "A feeling and a facial sign"], "why": "both"},
  {"a": "Different emotions, depending on the setting", "id": "psychology_0342", "p": "The same body arousal can feel like what?", "s": "Emotion and Motivation", "w": ["Exactly the same emotion, whatever the setting", "No emotion at all in any setting", "Only fear, whatever the setting"], "why": "both"},
  {"a": "Your expression can change how you feel", "id": "psychology_0343", "p": "What does the facial feedback idea suggest?", "s": "Emotion and Motivation", "w": ["Your feelings never show on your face", "Your face shows feelings but not more", "Your expression follows your feelings"], "why": "both"},
  {"a": "Disgust", "id": "psychology_0344", "p": "Which emotion is usually called universal?", "s": "Emotion and Motivation", "w": ["Jealousy", "Boredom", "Pride"], "why": "both"},
  {"a": "Yes, several are widely recognised", "id": "psychology_0345", "p": "Are basic facial expressions the same worldwide?", "s": "Emotion and Motivation", "w": ["Yes, but only among close relatives", "No, each culture invents its own", "No, only smiles are shared"], "why": "attribution"},
  {"a": "Basic needs come before higher ones", "id": "psychology_0346", "p": "What does the hierarchy of needs claim?", "s": "Emotion and Motivation", "w": ["Needs change only with a person's age", "All needs press equally at all times", "Higher needs come before basic ones"], "why": "both"},
  {"a": "Food, water, and sleep", "id": "psychology_0347", "p": "What is at the base of the hierarchy of needs?", "s": "Emotion and Motivation", "w": ["Safety and shelter", "Love and belonging", "Respect and esteem"], "why": "both"},
  {"a": "Reaching your full potential", "id": "psychology_0348", "p": "What is at the top of the hierarchy of needs?", "s": "Emotion and Motivation", "w": ["Feeling safe and free from danger", "Belonging to a close group", "Earning respect from others"], "why": "both"},
  {"a": "We act to reduce an inner need", "id": "psychology_0349", "p": "What does drive-reduction theory say?", "s": "Emotion and Motivation", "w": ["We act to raise our arousal level", "We act mainly out of plain habit", "We act only for outside rewards"], "why": "implausible-distractors"},
  {"a": "The body keeping a steady state", "id": "psychology_0350", "p": "What is homeostasis?", "s": "Emotion and Motivation", "w": ["The body changing state quickly", "The mind keeping a steady mood", "The body storing extra energy"], "why": "both"},
  {"a": "Best at a medium level", "id": "psychology_0351", "p": "How does arousal affect performance?", "s": "Emotion and Motivation", "w": ["Best at the highest level", "Best at the lowest level", "It has no effect at all"], "why": "both"},
  {"a": "An unlearned pattern of behaviour", "id": "psychology_0352", "p": "What is an instinct?", "s": "Emotion and Motivation", "w": ["A behaviour learned by reward", "A habit built by repetition", "A carefully planned action"], "why": "both"},
  {"a": "The weight the body returns to", "id": "psychology_0353", "p": "What is a set point for body weight?", "s": "Emotion and Motivation", "w": ["The weight a person was at birth", "The lowest weight that is safe", "A daily target for eating less"], "why": "both"},
  {"a": "The drive to reach a standard", "id": "psychology_0356", "p": "What is achievement motivation?", "s": "Emotion and Motivation", "w": ["The urge to reduce an inner need", "The need to belong to a group", "The wish to avoid all effort"], "why": "both"},
  {"a": "One choice is both good and bad", "id": "psychology_0357", "p": "What is an approach-avoidance conflict?", "s": "Emotion and Motivation", "w": ["No choice is available at all", "Two choices are both good", "Two choices are both bad"], "why": "both"},
  {"a": "The body readies to face or escape", "id": "psychology_0358", "p": "What is the fight-or-flight response?", "s": "Emotion and Motivation", "w": ["The body slows down and settles again", "The mind blanks out completely", "The body stores energy as fat"], "why": "both"},
  {"a": "Reading and managing feelings well", "id": "psychology_0359", "p": "What is emotional intelligence?", "s": "Emotion and Motivation", "w": ["Reasoning quickly about new problems", "Feeling every emotion very strongly", "Hiding your feelings from others"], "why": "both"},
  {"a": "Predicting how you will feel later", "id": "psychology_0360", "p": "What is affective forecasting?", "s": "Emotion and Motivation", "w": ["Predicting what you will do later", "Recalling how you felt long ago", "Measuring your heart rate daily"], "why": "both"},
  {"a": "How long the feelings will last", "id": "psychology_0361", "p": "What do people get wrong about future feelings?", "s": "Emotion and Motivation", "w": ["Whether they will feel anything", "Where they will be at the time", "Which feeling they will have"], "why": "both"},
  {"a": "Judging by your recent experience", "id": "psychology_0362", "p": "What is the adaptation-level phenomenon?", "s": "Emotion and Motivation", "w": ["Judging by other people's success", "Judging by the first number given", "Judging by how common a case is"], "why": "both"},
  {"a": "Feeling worse by comparing with others", "id": "psychology_0363", "p": "What is relative deprivation?", "s": "Emotion and Motivation", "w": ["Feeling worse after losing a friend", "Feeling better by helping others", "Feeling proud of your own success"], "why": "both"},
  {"a": "Releasing strong emotion to ease it", "id": "psychology_0364", "p": "What is catharsis?", "s": "Emotion and Motivation", "w": ["Changing the thought behind a feeling", "Naming an emotion to understand it", "Holding strong emotion inside you"], "why": "both"},
  {"a": "No, it often increases anger", "id": "psychology_0365", "p": "Does venting anger usually reduce it?", "s": "Emotion and Motivation", "w": ["No, it leaves anger unchanged", "Yes, it always removes anger", "Yes, but only among children"], "why": "both"},
  {"a": "Widen thinking and build resources", "id": "psychology_0366", "p": "What do positive emotions tend to do?", "s": "Emotion and Motivation", "w": ["Narrow thinking onto one threat", "Block new learning for a while", "Slow the body down completely"], "why": "both"},
  {"a": "A cultural rule about showing emotion", "id": "psychology_0367", "p": "What is a display rule?", "s": "Emotion and Motivation", "w": ["A rule about who may join a certain group", "A rule for scoring a lab result", "A step in the grieving process"], "why": "both"},
  {"a": "It tends to improve performance", "id": "psychology_0368", "p": "How does an audience affect a simple, practised task?", "s": "Emotion and Motivation", "w": ["It has no effect on performance", "It tends to harm performance", "It stops the task completely"], "why": "both"},
  {"a": "Satisfaction from the activity itself", "id": "psychology_0369", "p": "What is intrinsic reward?", "s": "Emotion and Motivation", "w": ["Money paid for finishing the work", "Praise offered by a manager", "A prize given at the very end"], "why": "both"},
  {"a": "People everywhere recognise it", "id": "psychology_0370", "p": "What does it mean to call an emotion universal?", "s": "Emotion and Motivation", "w": ["Only adults are able to feel it", "It can never be hidden at all", "It shows no signs in the body"], "why": "both"},
  {"a": "A usual pattern of thought and action", "id": "psychology_0371", "p": "What is personality?", "s": "Personality", "w": ["A level of general mental ability", "A set of skills learned at work", "A mood that changes day to day"], "why": "both"},
  {"a": "Conscientiousness", "id": "psychology_0372", "p": "Which trait is one of the Big Five?", "s": "Personality", "w": ["Assertiveness", "Independence", "Cheerfulness"], "why": "both"},
  {"a": "Being organised and dependable", "id": "psychology_0373", "p": "What does conscientiousness describe?", "s": "Personality", "w": ["Being calm under real pressure", "Being open to new experiences", "Being warm and cooperative"], "why": "both"},
  {"a": "Enjoying company and stimulation", "id": "psychology_0374", "p": "What does extraversion describe?", "s": "Personality", "w": ["Enjoying order and clear plans", "Enjoying new and strange ideas", "Enjoying quiet time alone"], "why": "both"},
  {"a": "Being kind and cooperative", "id": "psychology_0375", "p": "What does agreeableness describe?", "s": "Personality", "w": ["Being tidy and well organised", "Being curious and imaginative", "Being calm and even-tempered"], "why": "both"},
  {"a": "A tendency to worry and feel low", "id": "psychology_0376", "p": "What does neuroticism describe?", "s": "Personality", "w": ["A tendency to be calm and steady", "A tendency to seek out company", "A tendency to follow the rules"], "why": "both"},
  {"a": "Willingness to try new ideas", "id": "psychology_0377", "p": "What does openness describe in the Big Five?", "s": "Personality", "w": ["Willingness to help other people", "Willingness to follow the rules", "Willingness to work long hours"], "why": "both"},
  {"a": "The id", "id": "psychology_0378", "p": "Which part of the mind seeks immediate pleasure?", "s": "Personality", "w": ["The unconscious", "The superego", "The ego"], "why": "attribution"},
  {"a": "The superego", "id": "psychology_0379", "p": "Which part of the mind acts as the conscience?", "s": "Personality", "w": ["The unconscious", "The ego", "The id"], "why": "both"},
  {"a": "The ego", "id": "psychology_0380", "p": "Which part of the mind deals with reality?", "s": "Personality", "w": ["The unconscious", "The superego", "The id"], "why": "attribution"},
  {"a": "Pushing painful thoughts out of mind", "id": "psychology_0381", "p": "What is repression?", "s": "Personality", "w": ["Finding a good reason after the act", "Blaming your own faults on others", "Refusing to accept a hard truth"], "why": "both"},
  {"a": "Seeing your own faults in others", "id": "psychology_0382", "p": "What is projection as a defence?", "s": "Personality", "w": ["Pushing painful thoughts out of mind", "Acting the opposite of your feeling", "Turning an urge into useful work"], "why": "both"},
  {"a": "Refusing to accept a hard truth", "id": "psychology_0383", "p": "What is denial as a defence?", "s": "Personality", "w": ["Aiming a feeling at a safer target", "Giving a good reason after the act", "Seeing your own faults in others"], "why": "both"},
  {"a": "Inventing a good reason afterwards", "id": "psychology_0384", "p": "What is rationalisation as a defence?", "s": "Personality", "w": ["Pushing the real reason out of mind", "Doing the opposite of what you feel", "Aiming the feeling somewhere safer"], "why": "both"},
  {"a": "Aiming a feeling at a safer target", "id": "psychology_0385", "p": "What is displacement as a defence?", "s": "Personality", "w": ["Turning a feeling into useful work", "Seeing the feeling in someone else", "Denying that the feeling exists"], "why": "both"},
  {"a": "Turning an urge into useful work", "id": "psychology_0386", "p": "What is sublimation?", "s": "Personality", "w": ["Pushing an urge out of awareness", "Aiming an urge at a safer target", "Blaming an urge on someone else"], "why": "both"},
  {"a": "Acting the opposite of what you feel", "id": "psychology_0387", "p": "What is reaction formation?", "s": "Personality", "w": ["Acting on the first feeling you have", "Putting a feeling out of your mind", "Finding a reason for what you did"], "why": "both"},
  {"a": "Hidden conflicts from the past", "id": "psychology_0388", "p": "What does psychoanalysis mainly explore?", "s": "Personality", "w": ["Thoughts that cause low mood", "Habits shaped by rewards", "Goals a person sets today"], "why": "attribution"},
  {"a": "Images shared by all people", "id": "psychology_0389", "p": "What is the collective unconscious said to hold?", "s": "Personality", "w": ["Memories of your own childhood", "Facts learned during schooling", "Habits built up by practice"], "why": "both"},
  {"a": "A theme found across many cultures", "id": "psychology_0390", "p": "What is an archetype?", "s": "Personality", "w": ["A trait measured by a questionnaire", "A memory kept from early childhood", "A defence used to hide a feeling"], "why": "both"},
  {"a": "Acceptance without conditions", "id": "psychology_0391", "p": "What does a person need most in order to grow?", "s": "Personality", "w": ["Regular testing of progress", "Firm and steady discipline", "Competition with others"], "why": "attribution"},
  {"a": "Accepting someone without conditions", "id": "psychology_0392", "p": "What is unconditional positive regard?", "s": "Personality", "w": ["Praising only their very best results", "Rewarding them for good effort", "Correcting them in a kind way"], "why": "both"},
  {"a": "The picture you hold of yourself", "id": "psychology_0393", "p": "What is self-concept?", "s": "Personality", "w": ["The picture others hold of you", "The person you wish you were", "The role you play in a group"], "why": "both"},
  {"a": "Belief you can succeed at a task", "id": "psychology_0394", "p": "What is self-efficacy?", "s": "Personality", "w": ["Belief that the world is basically fair", "Belief that luck decides most", "Belief that others mean well"], "why": "both"},
  {"a": "Succeeding at a hard task", "id": "psychology_0395", "p": "What raises a person's sense of self-efficacy?", "s": "Personality", "w": ["Being praised for looking calm", "Watching a task go badly", "Avoiding any hard task"], "why": "attribution"},
  {"a": "Whether you feel events are yours to steer", "id": "psychology_0396", "p": "What is locus of control?", "s": "Personality", "w": ["Whether you can name your own feelings", "Whether you prefer company or quiet", "Whether you plan ahead or act now"], "why": "both"},
  {"a": "Their own actions shape events", "id": "psychology_0397", "p": "An internal locus of control means believing what?", "s": "Personality", "w": ["Luck decides most of what happens", "Events are mostly random chance", "Other people control their life"], "why": "both"},
  {"a": "A set of questions about usual behaviour", "id": "psychology_0398", "p": "What is a personality questionnaire?", "s": "Personality", "w": ["A set of unclear pictures to describe", "A timed test of reasoning ability", "A record of how fast you react"], "why": "both"},
  {"a": "A test using unclear images", "id": "psychology_0399", "p": "What is a projective test?", "s": "Personality", "w": ["A test scored against an age group", "A test of physical reaction time", "A test with true or false items"], "why": "both"},
  {"a": "Say what the shape looks like", "id": "psychology_0400", "p": "In an inkblot test, what does a person do?", "s": "Personality", "w": ["Rate each shape from one to ten", "Name the colour of the shape", "Copy the shape onto paper"], "why": "both"},
  {"a": "They are hard to score consistently", "id": "psychology_0401", "p": "Why are projective tests often criticised?", "s": "Personality", "w": ["They are too expensive for most clinics", "They cannot be given to adults", "They use too much arithmetic"], "why": "both"},
  {"a": "Changing behaviour to match a group", "id": "psychology_0402", "p": "What is conformity?", "s": "People and Groups", "w": ["Following an order from authority", "Helping a stranger in trouble", "Working better when watched"], "why": "both"},
  {"a": "Agree with the group anyway", "id": "psychology_0403", "p": "What do people often do when a group is clearly wrong?", "s": "People and Groups", "w": ["Correct the group at once", "Ask to see the evidence", "Leave the group quietly"], "why": "attribution"},
  {"a": "One other person also disagrees", "id": "psychology_0404", "p": "Conformity to a group drops most when what happens?", "s": "People and Groups", "w": ["The group repeats its answer twice", "The task is made harder to judge", "The group grows a little larger"], "why": "both"},
  {"a": "Following orders from an authority", "id": "psychology_0405", "p": "What is obedience?", "s": "People and Groups", "w": ["Helping a stranger in an emergency", "Matching the behaviour of a group", "Working harder when others watch"], "why": "both"},
  {"a": "Many more than we expect", "id": "psychology_0406", "p": "How many people obey an order they dislike?", "s": "People and Groups", "w": ["Only people who are paid well", "Only children and teenagers", "Almost nobody at all"], "why": "attribution"},
  {"a": "An authority who seems legitimate", "id": "psychology_0407", "p": "What makes people obey an uncomfortable order?", "s": "People and Groups", "w": ["A reward promised at the very end", "A group of friends watching them", "A task they already enjoy doing"], "why": "both"},
  {"a": "Change it a great deal", "id": "psychology_0408", "p": "What can a strong social role do to behaviour?", "s": "People and Groups", "w": ["Change it only in children", "Leave it much as it was", "Make it more honest"], "why": "attribution"},
  {"a": "People help less when others are near", "id": "psychology_0409", "p": "What is the bystander effect?", "s": "People and Groups", "w": ["People help more when others are near", "People help faster in a large crowd", "People help only those they know"], "why": "both"},
  {"a": "Each person feels less responsible", "id": "psychology_0410", "p": "What is diffusion of responsibility?", "s": "People and Groups", "w": ["One person takes all of the blame", "Nobody notices there is a problem", "Everybody acts at the same moment"], "why": "both"},
  {"a": "Doing easy tasks better when watched", "id": "psychology_0411", "p": "What is social facilitation?", "s": "People and Groups", "w": ["Doing hard tasks better when watched", "Doing every task worse when watched", "Doing less work inside a big group"], "why": "both"},
  {"a": "Putting in less effort within a group", "id": "psychology_0412", "p": "What is social loafing?", "s": "People and Groups", "w": ["Putting in more effort within a group", "Losing self-awareness inside a crowd", "Avoiding groups you do not know well"], "why": "both"},
  {"a": "Losing self-awareness in a crowd", "id": "psychology_0413", "p": "What is deindividuation?", "s": "People and Groups", "w": ["Losing interest in a large group", "Gaining a strong sense of self", "Leaving a group without a word"], "why": "both"},
  {"a": "A group avoids disagreement to agree", "id": "psychology_0414", "p": "What is groupthink?", "s": "People and Groups", "w": ["A group works better than one person", "A group argues about every detail", "A group splits into two halves"], "why": "both"},
  {"a": "Shared views become more extreme", "id": "psychology_0415", "p": "What is group polarisation?", "s": "People and Groups", "w": ["Shared views settle on a middle path", "Shared views are quickly forgotten", "Shared views split the group apart"], "why": "both"},
  {"a": "A small request first, a big one next", "id": "psychology_0416", "p": "What is the foot-in-the-door technique?", "s": "People and Groups", "w": ["A big request first, a small one next", "A threat first, then a small request", "A gift first, then a large request"], "why": "both"},
  {"a": "A big request first, a small one next", "id": "psychology_0417", "p": "What is the door-in-the-face technique?", "s": "People and Groups", "w": ["A small request first, a big one next", "The same request repeated many times", "A gift first, then a modest request"], "why": "both"},
  {"a": "Behaviour expected in a position", "id": "psychology_0418", "p": "What is a social role?", "s": "People and Groups", "w": ["A habit built over many years", "A rule written into the law", "A trait you are born with"], "why": "both"},
  {"a": "A belief or feeling that guides acts", "id": "psychology_0419", "p": "What is an attitude in psychology?", "s": "People and Groups", "w": ["A rule the group expects you to keep", "A skill learned by watching others", "A fixed idea about a whole group"], "why": "both"},
  {"a": "Convincing with facts and reasoning", "id": "psychology_0420", "p": "What is central route persuasion?", "s": "People and Groups", "w": ["Convincing with an attractive face", "Convincing by repeating a slogan", "Convincing by raising your voice"], "why": "both"},
  {"a": "Convincing with surface features", "id": "psychology_0421", "p": "What is peripheral route persuasion?", "s": "People and Groups", "w": ["Convincing by explaining details", "Convincing with careful evidence", "Convincing with written proof"], "why": "both"},
  {"a": "A negative attitude toward a group", "id": "psychology_0422", "p": "What is prejudice?", "s": "People and Groups", "w": ["Unfair treatment of a whole group", "A fixed idea about a whole group", "A fear of being in a large crowd"], "why": "both"},
  {"a": "Unfair treatment of a whole group", "id": "psychology_0423", "p": "What is discrimination in society?", "s": "People and Groups", "w": ["A negative attitude toward a group", "A fixed belief about a group", "A dislike of one person only"], "why": "both"},
  {"a": "Contact between groups can cut prejudice", "id": "psychology_0424", "p": "What does the contact hypothesis suggest?", "s": "People and Groups", "w": ["Contact between groups always raises it", "Contact has no effect on prejudice", "Contact works only among children"], "why": "both"},
  {"a": "Blaming one group unfairly for problems", "id": "psychology_0425", "p": "What is scapegoating?", "s": "People and Groups", "w": ["Praising one group far more than it deserves", "Avoiding every group but your own", "Leading a group in the wrong way"], "why": "both"},
  {"a": "Helping without expecting a reward", "id": "psychology_0426", "p": "What is altruism?", "s": "People and Groups", "w": ["Helping only when you are paid for it", "Helping only close family members", "Helping in order to look good"], "why": "both"},
  {"a": "A favour is expected to be returned", "id": "psychology_0427", "p": "What is the reciprocity norm?", "s": "People and Groups", "w": ["A leader is expected to speak first", "A group is expected to agree fully", "An order is expected to be obeyed"], "why": "both"},
  {"a": "People weigh the costs and benefits", "id": "psychology_0428", "p": "What does social exchange theory say about helping?", "s": "People and Groups", "w": ["People help without thinking at all", "People help purely out of instinct", "People never help total strangers"], "why": "both"},
  {"a": "An expectation that makes itself true", "id": "psychology_0429", "p": "What is a self-fulfilling prophecy?", "s": "People and Groups", "w": ["A prediction that always turns out wrong", "A memory of something that never was", "A wish that never comes true at all"], "why": "both"},
  {"a": "Worry about fitting a stereotype hurts you", "id": "psychology_0430", "p": "What is stereotype threat?", "s": "People and Groups", "w": ["Belonging to a group protects you from stress", "Fear of strangers keeps you alert", "A group threatens another group"], "why": "both"},
  {"a": "Each doubts, but thinks others agree", "id": "psychology_0431", "p": "What is pluralistic ignorance?", "s": "People and Groups", "w": ["Each agrees, but thinks others doubt", "Nobody in the group knows the facts", "Everybody speaks at the same time"], "why": "both"},
  {"a": "Judging yourself against other people", "id": "psychology_0432", "p": "What is social comparison?", "s": "People and Groups", "w": ["Judging two products side by side", "Judging others against yourself", "Judging a group by one member"], "why": "both"},
  {"a": "Copying others' gestures without noticing", "id": "psychology_0433", "p": "What is the chameleon effect?", "s": "People and Groups", "w": ["Changing the clothes you wear to fit a group", "Hiding your true feelings from others", "Blending quietly into a background"], "why": "both"},
  {"a": "Thinking others can read your feelings", "id": "psychology_0434", "p": "What is the illusion of transparency?", "s": "People and Groups", "w": ["Thinking others notice how you look", "Thinking you can read others well", "Thinking your feelings never show"], "why": "both"},
  {"a": "Being near each other often", "id": "psychology_0435", "p": "Which factor most reliably increases attraction?", "s": "People and Groups", "w": ["Holding completely opposite opinions", "Meeting only once a year", "Living in different cities"], "why": "both"},
  {"a": "Intense excitement and longing", "id": "psychology_0436", "p": "What is passionate love?", "s": "People and Groups", "w": ["Calm affection built over years", "Respect without any closeness", "Friendship with no romance"], "why": "both"},
  {"a": "Deep affection and commitment", "id": "psychology_0437", "p": "What is companionate love?", "s": "People and Groups", "w": ["Sudden and intense attraction", "A short and lively crush", "A liking for a hobby"], "why": "both"},
  {"a": "Both give and receive fairly", "id": "psychology_0438", "p": "What is equity in a relationship?", "s": "People and Groups", "w": ["One gives far more than the other", "Both compete for the upper hand", "Neither one gives very much"], "why": "both"},
  {"a": "Sharing personal information", "id": "psychology_0439", "p": "What is self-disclosure?", "s": "People and Groups", "w": ["Hiding your past from others", "Speaking in front of a crowd", "Writing a diary for yourself"], "why": "both"},
  {"a": "An actor working with the researcher", "id": "psychology_0440", "p": "What is a confederate in a psychology study?", "s": "People and Groups", "w": ["A person who refuses to take part", "A second researcher who observes", "A participant picked at random"], "why": "both"},
  {"a": "Close by and seeming official", "id": "psychology_0441", "p": "Obedience rises when the authority is what?", "s": "People and Groups", "w": ["Far away and unknown to you", "One of the other participants", "Completely silent throughout"], "why": "both"},
  {"a": "An unwritten rule about behaviour", "id": "psychology_0442", "p": "What is a norm in social psychology?", "s": "People and Groups", "w": ["An average score across a group", "A written law set by a country", "A role played inside one group"], "why": "both"},
  {"a": "It usually increases liking", "id": "psychology_0443", "p": "How does seeing a person often affect liking?", "s": "People and Groups", "w": ["It reverses liking completely", "It has no effect on liking", "It usually reduces liking"], "why": "both"},
  {"a": "Seeing others refuse to obey", "id": "psychology_0444", "p": "What makes obedience most likely to decrease?", "s": "People and Groups", "w": ["A larger reward for obeying", "A firmer and louder order", "A closer authority figure"], "why": "both"},
  {"a": "Excessive admiration of one leader", "id": "psychology_0445", "p": "What is a cult of personality?", "s": "People and Groups", "w": ["A study of many different personality types", "A questionnaire about traits", "A group with no leader at all"], "why": "both"},
  {"a": "It shapes norms, values, and behaviour", "id": "psychology_0446", "p": "What is culture's role in psychology?", "s": "People and Groups", "w": ["It affects only the language we speak", "It has no measurable effect at all", "It affects only the food we choose"], "why": "both"},
  {"a": "Personal goals come first", "id": "psychology_0447", "p": "What is individualism as a cultural value?", "s": "People and Groups", "w": ["Tradition decides everything", "Older members decide first", "Group harmony comes first"], "why": "both"},
  {"a": "Listing and describing disorders", "id": "psychology_0448", "p": "What is the DSM used for?", "s": "Mental Health", "w": ["Measuring general intelligence", "Training new therapists", "Scanning the living brain"], "why": "both"},
  {"a": "Fear that is out of proportion", "id": "psychology_0449", "p": "Anxiety disorders are generally marked by what?", "s": "Mental Health", "w": ["Beliefs that are clearly false", "Mood that stays very high", "Loss of recent memories"], "why": "both"},
  {"a": "Intense fear of one thing", "id": "psychology_0450", "p": "What is a phobia?", "s": "Mental Health", "w": ["Constant worry about many things", "Repeated unwanted thoughts", "A long spell of low mood"], "why": "both"},
  {"a": "Fear of places hard to escape", "id": "psychology_0451", "p": "What is agoraphobia?", "s": "Mental Health", "w": ["Fear of being watched closely", "Fear of small, closed spaces", "Fear of speaking to a group"], "why": "both"},
  {"a": "Sudden intense fear with body symptoms", "id": "psychology_0452", "p": "What is a panic attack?", "s": "Mental Health", "w": ["A spell of unusually high energy and mood", "A slow drop in mood over months", "A period of blank, lost memory"], "why": "both"},
  {"a": "Constant worry about many things", "id": "psychology_0453", "p": "What is generalised anxiety disorder?", "s": "Mental Health", "w": ["Sudden and brief attacks of terror", "Intense fear of one object", "Low mood only in the winter"], "why": "both"},
  {"a": "Unwanted thoughts plus repeated acts", "id": "psychology_0454", "p": "What is obsessive-compulsive disorder?", "s": "Mental Health", "w": ["Sudden swings between two opposite moods", "Fear of social situations only", "Loss of interest in everything"], "why": "both"},
  {"a": "A repeated act to reduce distress", "id": "psychology_0455", "p": "What is a compulsion?", "s": "Mental Health", "w": ["An unwanted thought that keeps returning", "A firm belief that is untrue", "A vivid and frightening dream"], "why": "both"},
  {"a": "An unwanted thought that returns", "id": "psychology_0456", "p": "What is an obsession in OCD?", "s": "Mental Health", "w": ["A repeated act to reduce distress", "A physical symptom with no cause", "A sensation that is not real"], "why": "both"},
  {"a": "Lasting distress after a trauma", "id": "psychology_0457", "p": "What is post-traumatic stress disorder?", "s": "Mental Health", "w": ["Worry with no clear cause at all", "Fear of one specific object", "Mood that lifts every summer"], "why": "both"},
  {"a": "Low mood and loss of interest", "id": "psychology_0458", "p": "Major depression is marked by what?", "s": "Mental Health", "w": ["Hearing voices that are not there", "High energy lasting for weeks", "Repeated washing of the hands"], "why": "both"},
  {"a": "Depression alternating with mania", "id": "psychology_0459", "p": "What is bipolar disorder?", "s": "Mental Health", "w": ["Constant worry about everything", "Two separate identities in one", "A strong fear of open spaces"], "why": "both"},
  {"a": "A spell of very high energy and mood", "id": "psychology_0460", "p": "What is mania?", "s": "Mental Health", "w": ["A spell of deep and long-lasting sadness", "A sudden attack of intense fear", "A loss of interest in food"], "why": "both"},
  {"a": "Depression that follows the seasons", "id": "psychology_0461", "p": "What is seasonal affective disorder?", "s": "Mental Health", "w": ["Anxiety that follows the weather forecast", "Sleepiness that follows meals", "Fear of cold and dark places"], "why": "both"},
  {"a": "Disturbed thinking and perception", "id": "psychology_0462", "p": "What is schizophrenia?", "s": "Mental Health", "w": ["Two separate identities in one person", "Extreme fear of other people", "A steady loss of old memories"], "why": "both"},
  {"a": "A firm belief that is false", "id": "psychology_0463", "p": "What is a delusion?", "s": "Mental Health", "w": ["A sensation that is not real", "A sudden wave of strong fear", "A repeated act done to cope"], "why": "both"},
  {"a": "Sensing something that is not there", "id": "psychology_0464", "p": "What is a hallucination?", "s": "Mental Health", "w": ["Believing something that is clearly untrue", "Forgetting something recent", "Repeating something many times"], "why": "both"},
  {"a": "Added experiences like hallucinations", "id": "psychology_0465", "p": "What are positive symptoms of schizophrenia?", "s": "Mental Health", "w": ["Reduced emotion, speech, and motivation", "Improved mood and clear focus", "Better memory for recent events"], "why": "both"},
  {"a": "Reduced emotion, speech, and drive", "id": "psychology_0466", "p": "What are negative symptoms of schizophrenia?", "s": "Mental Health", "w": ["Added hallucinations and delusions", "Increased energy and fast speech", "Improved memory and attention"], "why": "both"},
  {"a": "Limiting food with fear of weight gain", "id": "psychology_0467", "p": "What is anorexia nervosa?", "s": "Mental Health", "w": ["Overeating and then trying hard to undo it", "Eating only late at night", "Avoiding one group of foods"], "why": "both"},
  {"a": "Overeating then trying to undo it", "id": "psychology_0468", "p": "What is bulimia nervosa?", "s": "Mental Health", "w": ["Limiting food with fear of weight gain", "Eating only sweet foods each day", "Skipping breakfast most mornings"], "why": "both"},
  {"a": "A lasting pattern that causes trouble", "id": "psychology_0469", "p": "What is a personality disorder?", "s": "Mental Health", "w": ["A brief change in a person's mood or energy", "A short reaction to a hard event", "A physical illness of the brain"], "why": "both"},
  {"a": "Disregard for the rights of others", "id": "psychology_0470", "p": "Antisocial personality disorder is marked by what?", "s": "Mental Health", "w": ["Extreme shyness in all social groups", "Strong fear of being left alone", "Repeated checking of small things"], "why": "both"},
  {"a": "Unstable moods and relationships", "id": "psychology_0471", "p": "Borderline personality disorder is marked by what?", "s": "Mental Health", "w": ["A complete absence of emotion", "Loss of memory for recent days", "Fear of one specific object"], "why": "both"},
  {"a": "Feeling cut off from yourself", "id": "psychology_0472", "p": "What is dissociation?", "s": "Mental Health", "w": ["Feeling sleepy in the daytime", "Feeling unusually cheerful", "Feeling weak in the muscles"], "why": "both"},
  {"a": "Two or more identities in one person", "id": "psychology_0473", "p": "What is dissociative identity disorder?", "s": "Mental Health", "w": ["A split between the two brain halves", "A disorder with two known causes", "A problem of seeing two images"], "why": "both"},
  {"a": "Trouble with attention and stillness", "id": "psychology_0474", "p": "What is ADHD?", "s": "Mental Health", "w": ["Trouble with reading and spelling", "Trouble with balance and movement", "Trouble with mood across the year"], "why": "both"},
  {"a": "Social communication and behaviour", "id": "psychology_0475", "p": "Autism involves differences in what?", "s": "Mental Health", "w": ["Hearing, eyesight, and muscle strength", "Height, weight, and body shape", "Appetite, sleep, and digestion"], "why": "both"},
  {"a": "A weakness plus stress can cause illness", "id": "psychology_0476", "p": "What does the diathesis-stress model say?", "s": "Mental Health", "w": ["Stress on its own causes every known disorder", "Disorders arise without any cause", "Genes alone cause every disorder"], "why": "both"},
  {"a": "Looking at body, mind, and setting", "id": "psychology_0477", "p": "What is the biopsychosocial approach?", "s": "Mental Health", "w": ["Looking only at a person's culture", "Looking only at brain chemistry", "Looking only at early childhood"], "why": "both"},
  {"a": "Having two conditions at once", "id": "psychology_0478", "p": "What is comorbidity?", "s": "Mental Health", "w": ["Getting a condition from medicine", "Having a very rare condition", "Recovering from a condition"], "why": "both"},
  {"a": "Negative attitudes toward those affected", "id": "psychology_0479", "p": "What is stigma in mental health?", "s": "Mental Health", "w": ["A symptom listed in the diagnostic manual", "A method used in group therapy", "A code used for a diagnosis"], "why": "both"},
  {"a": "Body symptoms with great distress", "id": "psychology_0480", "p": "What is a somatic symptom disorder?", "s": "Mental Health", "w": ["A strong fear of visiting the doctor", "A condition with no symptoms", "A rash brought on by worry"], "why": "both"},
  {"a": "Treating disorders like illnesses", "id": "psychology_0481", "p": "What is the medical model in psychology?", "s": "Mental Health", "w": ["Treating all behaviour as learned", "Treating diagnosis as unhelpful", "Treating only through talking"], "why": "both"},
  {"a": "How common a condition is", "id": "psychology_0482", "p": "What does a prevalence rate tell you?", "s": "Mental Health", "w": ["How severe a condition is", "How long treatment takes", "How well treatment works"], "why": "both"},
  {"a": "No, most are not violent", "id": "psychology_0483", "p": "Are most people with a mental illness violent?", "s": "Mental Health", "w": ["Yes, but only when untreated", "Yes, nearly all of them are", "Only those who live alone"], "why": "implausible-distractors"},
  {"a": "Recovering well after hardship", "id": "psychology_0484", "p": "What is resilience?", "s": "Mental Health", "w": ["Avoiding every kind of stress", "Forgetting all bad events", "Never feeling sad at all"], "why": "both"},
  {"a": "It often improves the outcome", "id": "psychology_0485", "p": "Why is early treatment of mental illness helpful?", "s": "Mental Health", "w": ["It makes symptoms worse first", "It helps only young children", "It has no effect on outcome"], "why": "both"},
  {"a": "Treating difficulty by talking", "id": "psychology_0486", "p": "What is psychotherapy?", "s": "Therapy and Treatment", "w": ["Treating illness with medicine", "Treating illness by surgery", "Treating illness with rest"], "why": "both"},
  {"a": "Changing unhelpful thoughts and acts", "id": "psychology_0487", "p": "What is cognitive behavioural therapy?", "s": "Therapy and Treatment", "w": ["Exploring dreams for hidden meaning", "Offering warmth and full acceptance", "Rewarding wanted behaviour only"], "why": "both"},
  {"a": "Gradually facing a feared thing", "id": "psychology_0488", "p": "What is exposure therapy?", "s": "Therapy and Treatment", "w": ["Steadily avoiding a feared thing", "Taking medicine to ease a fear", "Talking about a fear's origin"], "why": "both"},
  {"a": "Facing a fear fully and at once", "id": "psychology_0489", "p": "What is flooding in therapy?", "s": "Therapy and Treatment", "w": ["Facing a fear in very small steps", "Talking about a fear each week", "Writing a fear down every day"], "why": "both"},
  {"a": "Pairing a habit with something nasty", "id": "psychology_0490", "p": "What is aversion therapy?", "s": "Therapy and Treatment", "w": ["Pairing a habit with a small reward", "Replacing a habit with a new one", "Talking a habit through slowly"], "why": "both"},
  {"a": "The therapist offers warmth and acceptance", "id": "psychology_0491", "p": "What is client-centred therapy?", "s": "Therapy and Treatment", "w": ["The therapist gives firm and clear instructions", "The therapist stays silent throughout", "The therapist decides on the medicine"], "why": "both"},
  {"a": "The client", "id": "psychology_0492", "p": "In client-centred therapy, who leads the session?", "s": "Therapy and Treatment", "w": ["A family member", "A group leader", "The therapist"], "why": "attribution"},
  {"a": "Saying whatever comes to mind", "id": "psychology_0493", "p": "What is free association?", "s": "Therapy and Treatment", "w": ["Answering a set of fixed questions", "Repeating one phrase out loud", "Writing in a diary each night"], "why": "both"},
  {"a": "Old feelings redirected at the therapist", "id": "psychology_0494", "p": "What is transference in therapy?", "s": "Therapy and Treatment", "w": ["Moving on to a completely different therapist", "Passing a diagnosis to a doctor", "Copying the therapist's manner"], "why": "both"},
  {"a": "Several clients meet with one therapist", "id": "psychology_0495", "p": "What is group therapy?", "s": "Therapy and Treatment", "w": ["One client meets with several therapists", "A public talk given to an audience", "A whole family meets on its own"], "why": "both"},
  {"a": "Treating the family as one system", "id": "psychology_0496", "p": "What is family therapy?", "s": "Therapy and Treatment", "w": ["Treating one family member alone", "Teaching parents a set of skills", "Testing the children in a family"], "why": "both"},
  {"a": "Using reinforcement to change acts", "id": "psychology_0497", "p": "What is behaviour modification?", "s": "Therapy and Treatment", "w": ["Exploring the unconscious mind deeply", "Changing a written diagnosis", "Prescribing a daily medicine"], "why": "both"},
  {"a": "Depression and often anxiety", "id": "psychology_0499", "p": "What are antidepressant medicines used for?", "s": "Therapy and Treatment", "w": ["Hallucinations and delusions", "Very high mood and energy", "Trouble with attention"], "why": "both"},
  {"a": "Hallucinations and delusions", "id": "psychology_0500", "p": "What are antipsychotic medicines mainly used for?", "s": "Therapy and Treatment", "w": ["Mild everyday low mood", "Trouble getting to sleep", "Worry about many things"], "why": "both"},
  {"a": "Bipolar disorder", "id": "psychology_0501", "p": "Lithium is often used to treat what?", "s": "Therapy and Treatment", "w": ["A specific phobia", "Panic attacks", "Insomnia"], "why": "both"},
  {"a": "Brief electrical stimulation of the brain", "id": "psychology_0502", "p": "What is electroconvulsive therapy?", "s": "Therapy and Treatment", "w": ["Surgery that cuts connections in the brain", "A course of talking treatment", "A daily injection of vitamins"], "why": "both"},
  {"a": "Severe depression that has not improved", "id": "psychology_0503", "p": "What is electroconvulsive therapy mainly used for?", "s": "Therapy and Treatment", "w": ["Everyday stress at work or in the home", "Trouble falling asleep at night", "A simple fear of one animal"], "why": "both"},
  {"a": "An operation cutting frontal connections", "id": "psychology_0504", "p": "What was a lobotomy?", "s": "Therapy and Treatment", "w": ["A scan that maps activity across the brain", "An exercise to rebuild memory", "A treatment that uses talking"], "why": "both"},
  {"a": "It caused severe and lasting harm", "id": "psychology_0505", "p": "Why was the lobotomy abandoned?", "s": "Therapy and Treatment", "w": ["It was far too costly for hospitals", "It took many years to complete", "It worked far too quickly"], "why": "both"},
  {"a": "To compare against no real treatment", "id": "psychology_0506", "p": "Why do drug trials include a placebo group?", "s": "Therapy and Treatment", "w": ["To reduce the cost of the medicine", "To finish the study more quickly", "To treat more patients at once"], "why": "both"},
  {"a": "Replacing unhelpful thoughts", "id": "psychology_0507", "p": "What is cognitive restructuring?", "s": "Therapy and Treatment", "w": ["Rebuilding damaged brain tissue", "Changing a daily routine", "Relearning a lost skill"], "why": "both"},
  {"a": "Attending to the present moment", "id": "psychology_0508", "p": "What is mindfulness in therapy?", "s": "Therapy and Treatment", "w": ["Planning the week ahead carefully", "Recalling your early childhood", "Emptying the mind completely"], "why": "both"},
  {"a": "Symptoms returning after improvement", "id": "psychology_0509", "p": "What is a relapse?", "s": "Therapy and Treatment", "w": ["Symptoms appearing for the first time", "A complete and lasting recovery", "A change to a different therapist"], "why": "both"},
  {"a": "Treatment supported by research", "id": "psychology_0510", "p": "What does evidence-based therapy mean?", "s": "Therapy and Treatment", "w": ["Treatment based on long tradition", "Treatment chosen by the client", "Treatment given free of charge"], "why": "both"},
  {"a": "The trusting bond with the therapist", "id": "psychology_0511", "p": "What is the therapeutic alliance?", "s": "Therapy and Treatment", "w": ["A licence to practise as a therapist", "A group of clinics working together", "An agreement about the session fee"], "why": "both"},
  {"a": "Measure reactions under set conditions", "id": "psychology_0512", "p": "What did the first psychology laboratory do?", "s": "How Psychology Is Studied", "w": ["Treat patients with severe illness", "Train teachers for new schools", "Record dreams told by patients"], "why": "attribution"},
  {"a": "Careful measurement in a laboratory", "id": "psychology_0513", "p": "What marks the start of psychology as a science?", "s": "How Psychology Is Studied", "w": ["Careful reading of old writings", "Study of the shape of the skull", "Long talks about the soul"], "why": "attribution"},
  {"a": "Breaking experience into basic parts", "id": "psychology_0514", "p": "What was structuralism about?", "s": "How Psychology Is Studied", "w": ["Studying only the behaviour you can see", "Exploring wishes kept hidden", "Measuring general intelligence"], "why": "both"},
  {"a": "What purpose does a mental process serve?", "id": "psychology_0515", "p": "What question does functionalism ask?", "s": "How Psychology Is Studied", "w": ["What separate parts make up a single thought?", "What chemicals carry each signal?", "What wish lies behind each act?"], "why": "attribution"},
  {"a": "The purpose mental processes serve", "id": "psychology_0516", "p": "What did functionalism focus on?", "s": "How Psychology Is Studied", "w": ["The parts that make up a single thought", "The conflicts hidden in childhood", "The chemistry of the brain"], "why": "both"},
  {"a": "Only what can be observed", "id": "psychology_0517", "p": "What does behaviourism study?", "s": "How Psychology Is Studied", "w": ["Only what is felt inside", "Only what is remembered", "Only what is dreamed"], "why": "attribution"},
  {"a": "Behaviour that can be observed", "id": "psychology_0518", "p": "What did behaviourism say psychology should study?", "s": "How Psychology Is Studied", "w": ["Memories from early childhood", "Wishes kept out of awareness", "Pictures taken of the brain"], "why": "both"},
  {"a": "Recalling one when you see the other", "id": "psychology_0519", "p": "Learning two items together makes what easier?", "s": "Memory", "w": ["Recalling both at the very same time", "Forgetting both after a short while", "Storing both as a single picture"], "why": "attribution"},
  {"a": "Finding pupils who needed extra help", "id": "psychology_0520", "p": "What was the first intelligence test built for?", "s": "Intelligence and Testing", "w": ["Choosing soldiers for officer roles", "Ranking adults by their earnings", "Testing memory in older people"], "why": "attribution"},
  {"a": "You against others of your age", "id": "psychology_0521", "p": "What does an intelligence test score compare?", "s": "Intelligence and Testing", "w": ["You against your own past score", "You against the hardest items", "You against a fixed pass mark"], "why": "attribution"},
  {"a": "How people vary from one another", "id": "psychology_0522", "p": "What do individual differences describe?", "s": "Intelligence and Testing", "w": ["How people learn from a reward", "How people group into cultures", "How people change with age"], "why": "attribution"},
  {"a": "Food, water, warmth, and rest", "id": "psychology_0523", "p": "In the hierarchy of needs, what comes first?", "s": "Emotion and Motivation", "w": ["Respect from other people", "Close and loving bonds", "A sense of achievement"], "why": "attribution"},
  {"a": "Human potential and personal growth", "id": "psychology_0524", "p": "What does humanistic psychology emphasise?", "s": "Personality", "w": ["Hidden conflict left from childhood", "Behaviour you can observe only", "The chemistry of the brain alone"], "why": "both"},
  {"a": "Unhelpful patterns of thought", "id": "psychology_0525", "p": "What does cognitive therapy target in depression?", "s": "Therapy and Treatment", "w": ["Hidden wishes from childhood", "Rewards that shape behaviour", "Levels of brain chemicals"], "why": "attribution"},
  {"a": "Bargaining", "id": "psychology_0526", "p": "What is one commonly named stage of grief?", "s": "Emotion and Motivation", "w": ["Reflection", "Withdrawal", "Detachment"], "why": "attribution"},
  {"a": "No, the stages often overlap", "id": "psychology_0527", "p": "Do people always move through grief in order?", "s": "Emotion and Motivation", "w": ["Yes, but only for close family", "Yes, always in a fixed order", "No, grief has just one stage"], "why": "both"},
  {"a": "A shared goal they both need", "id": "psychology_0528", "p": "What reduces conflict between two rival groups?", "s": "People and Groups", "w": ["A leader chosen from one group", "A contest with a single prize", "Keeping the groups well apart"], "why": "attribution"},
  {"a": "Within days, given a shared label", "id": "psychology_0529", "p": "How quickly can strangers form a strong group?", "s": "People and Groups", "w": ["Only after several long years", "Only when they are related", "Only if a leader is chosen"], "why": "attribution"},
  {"a": "Waiting now for a better reward", "id": "psychology_0530", "p": "What does delayed gratification mean?", "s": "Emotion and Motivation", "w": ["Taking the smaller reward now", "Sharing a reward with others", "Refusing every offered reward"], "why": "attribution"},
  {"a": "By pairing a thing with a scare", "id": "psychology_0531", "p": "How is a fear most often learned?", "s": "Learning and Conditioning", "w": ["By hearing about it from others", "By reading a warning about it", "By being born already afraid"], "why": "attribution"},
  {"a": "Yes, to things that look alike", "id": "psychology_0532", "p": "Can a learned fear spread to similar things?", "s": "Learning and Conditioning", "w": ["No, it stays with one thing", "Yes, but only after a year", "No, it fades within a day"], "why": "attribution"},
  {"a": "Comfort and contact, not just food", "id": "psychology_0533", "p": "What matters most for an infant's attachment?", "s": "How People Develop", "w": ["Food and warmth, with no need for contact", "Play with others the same age", "Being left alone to settle"], "why": "attribution"},
  {"a": "People change when they are watched", "id": "psychology_0534", "p": "What is the Hawthorne effect?", "s": "How Psychology Is Studied", "w": ["People work better in bright light", "People work worse in a large group", "People forget they are in a study"], "why": "both"},
  {"a": "A reflex triggered by a learned signal", "id": "psychology_0535", "p": "What is a conditioned reflex?", "s": "Learning and Conditioning", "w": ["A reflex present from the first day", "A reflex handled by the spinal cord", "A reflex that fades with practice"], "why": "attribution"},
  {"a": "Several separate kinds of ability", "id": "psychology_0536", "p": "What does a multiple intelligences view claim?", "s": "Intelligence and Testing", "w": ["One general ability behind all", "Ability fixed at birth for life", "Ability that cannot be measured"], "why": "attribution"},
  {"a": "Know-how for everyday problems", "id": "psychology_0537", "p": "Practical intelligence is best described as what?", "s": "Intelligence and Testing", "w": ["Speed at solving puzzles", "Knowledge of many facts", "Skill at making new things"], "why": "attribution"},
  {"a": "They learn grammar without being taught", "id": "psychology_0538", "p": "What suggests children are built to learn language?", "s": "How People Develop", "w": ["They copy every word they are told", "They speak only after formal lessons", "They learn faster than adults do"], "why": "attribution"},
  {"a": "How children's thinking changes", "id": "psychology_0539", "p": "What does cognitive development describe?", "s": "How People Develop", "w": ["How children form close bonds", "How children learn to walk", "How children make friends"], "why": "attribution"},
  {"a": "Within a short early window", "id": "psychology_0540", "p": "When does imprinting have to happen?", "s": "How People Develop", "w": ["At any time during life", "Only after the first year", "Only in the second year"], "why": "attribution"},
  {"a": "A rapid early bond to a carer", "id": "psychology_0541", "p": "What is imprinting?", "s": "How People Develop", "w": ["A slow bond built over years", "A fear learned from a scare", "A habit built by repetition"], "why": "both"},
  {"a": "All at once, without trial and error", "id": "psychology_0542", "p": "How do animals sometimes solve a new problem?", "s": "Learning and Conditioning", "w": ["Only by slow trial and error over time", "Only by copying a human", "Only after many rewards"], "why": "attribution"},
  {"a": "Where a person draws energy from", "id": "psychology_0543", "p": "What do introversion and extraversion describe?", "s": "Personality", "w": ["How quickly a person learns a new skill", "How well a person recalls", "How honest a person is"], "why": "attribution"},
  {"a": "A source of unhappiness", "id": "psychology_0544", "p": "What is the gap between real and ideal self?", "s": "Personality", "w": ["A sign of good health", "A kind of memory error", "A stage of childhood"], "why": "attribution"},
  {"a": "A move toward humane treatment", "id": "psychology_0545", "p": "What changed in the care of mental patients?", "s": "Therapy and Treatment", "w": ["A move toward longer stays", "A move toward more testing", "A move toward home nursing"], "why": "attribution"},
  {"a": "Intelligence quotient", "id": "psychology_0546", "p": "What does IQ stand for?", "s": "Intelligence and Testing", "w": ["Intelligence quality", "Individual quotient", "Intellect quality"], "why": "implausible-distractors"},
  {"a": "Scores compared to a tested group", "id": "psychology_0548", "p": "What does standardisation of a test mean?", "s": "Intelligence and Testing", "w": ["The test gives the same result twice", "The test measures the right thing", "The test is used around the world"], "why": "both"},
  {"a": "It gives consistent results", "id": "psychology_0549", "p": "What does reliability of a test mean?", "s": "Intelligence and Testing", "w": ["It compares you to your age group", "It has been tested on many people", "It measures the right thing"], "why": "implausible-distractors"},
  {"a": "It measures what it claims to", "id": "psychology_0550", "p": "What does validity of a test mean?", "s": "Intelligence and Testing", "w": ["It gives the same score twice", "It is quick and easy to take", "It compares you to a group"], "why": "both"},
  {"a": "A bell-shaped spread of scores", "id": "psychology_0551", "p": "What is a normal distribution?", "s": "Intelligence and Testing", "w": ["A straight line rising steadily", "A spread with two peaks", "A spread with no middle"], "why": "both"},
  {"a": "Musical ability", "id": "psychology_0552", "p": "Which is often named as a separate intelligence?", "s": "Intelligence and Testing", "w": ["Reaction time", "Reading speed", "Memory span"], "why": "both"},
  {"a": "Analytical, creative, and practical", "id": "psychology_0553", "p": "What three parts does the triarchic theory describe?", "s": "Intelligence and Testing", "w": ["Verbal, musical, and spatial ability", "Fluid, crystallised, and fixed", "Memory, attention, and speed"], "why": "both"},
  {"a": "Average scores rise across generations", "id": "psychology_0554", "p": "What is the Flynn effect?", "s": "Intelligence and Testing", "w": ["Average scores fall across generations", "Average scores vary by season", "Average scores never change"], "why": "both"},
  {"a": "A general ability behind many tasks", "id": "psychology_0555", "p": "What is the g factor?", "s": "Intelligence and Testing", "w": ["A gene that is linked to school success", "A grade given on a report card", "A store for facts and meanings"], "why": "both"},
  {"a": "Great skill in one narrow area", "id": "psychology_0556", "p": "What is savant syndrome?", "s": "Intelligence and Testing", "w": ["High scores across every kind of test", "An inability to learn at all", "A loss of memory in old age"], "why": "both"},
  {"a": "What a person has already learned", "id": "psychology_0557", "p": "What does an achievement test measure?", "s": "Intelligence and Testing", "w": ["How fast a person is able to learn", "What a person is like inside", "How quickly a person reacts"], "why": "both"},
  {"a": "How well someone could learn", "id": "psychology_0558", "p": "What does an aptitude test try to predict?", "s": "Intelligence and Testing", "w": ["What someone has already learned", "How someone feels today", "How healthy someone is"], "why": "both"},
  {"a": "The share of people scoring below", "id": "psychology_0559", "p": "What does a percentile rank tell you?", "s": "Intelligence and Testing", "w": ["The number of items you got right", "The age group you belong to", "The time you took to finish"], "why": "both"},
  {"a": "A test that unfairly favours a group", "id": "psychology_0560", "p": "What is test bias?", "s": "Intelligence and Testing", "w": ["A test that takes far too long to finish", "A test printed in small type", "A test given on two occasions"], "why": "both"},
  {"a": "No, they cover a limited range", "id": "psychology_0561", "p": "Do IQ tests measure every kind of ability?", "s": "Intelligence and Testing", "w": ["Yes, they measure every ability", "No, they measure only speed", "Yes, but only for adults"], "why": "both"},
  {"a": "No, they are different abilities", "id": "psychology_0562", "p": "Is emotional intelligence the same as IQ?", "s": "Intelligence and Testing", "w": ["Yes, they are two names for one thing", "Yes, but only among children", "No, one replaces the other"], "why": "both"},
  {"a": "How much of the variation links to genes", "id": "psychology_0563", "p": "What does heritability of intelligence describe?", "s": "Intelligence and Testing", "w": ["The exact score a child will one day reach", "Whether a score can ever change", "How much a school raises a score"], "why": "both"},
  {"a": "Justifying unfair treatment of groups", "id": "psychology_0564", "p": "What was an early misuse of intelligence testing?", "s": "Intelligence and Testing", "w": ["Helping pupils choose their school subjects", "Measuring simple reaction times", "Training teachers in new methods"], "why": "both"},
  {"a": "The mind and body's response to demands", "id": "psychology_0565", "p": "What is stress in psychology?", "s": "Stress and Health", "w": ["An illness that affects the nervous system", "A physical injury to the body", "A fixed trait of personality"], "why": "both"},
  {"a": "Anything that causes stress", "id": "psychology_0566", "p": "What is a stressor?", "s": "Stress and Health", "w": ["A chemical made in the brain", "The body's calming response", "A stage of deep, slow sleep"], "why": "both"},
  {"a": "Alarm, resistance, then exhaustion", "id": "psychology_0567", "p": "How does the body respond to long stress?", "s": "Stress and Health", "w": ["Alarm, recovery, then a return to normal", "Denial, anger, then acceptance", "Input, storage, then output"], "why": "both"},
  {"a": "Exhaustion", "id": "psychology_0568", "p": "What is the last stage of long-term stress?", "s": "Stress and Health", "w": ["Resistance", "Adaptation", "Alarm"], "why": "attribution"},
  {"a": "Stress that feels positive", "id": "psychology_0569", "p": "What is eustress?", "s": "Stress and Health", "w": ["Stress with no feeling at all", "Stress that lasts for years", "Stress that feels harmful"], "why": "both"},
  {"a": "Stress that feels harmful", "id": "psychology_0570", "p": "What is distress in this context?", "s": "Stress and Health", "w": ["Stress that feels positive", "Stress that comes and goes", "Stress you do not notice"], "why": "both"},
  {"a": "Weakens it", "id": "psychology_0571", "p": "What does long-term stress do to the immune system?", "s": "Stress and Health", "w": ["Leaves it alone", "Strengthens it", "Replaces it"], "why": "implausible-distractors"},
  {"a": "Competitive, impatient, hurried", "id": "psychology_0572", "p": "What is Type A behaviour?", "s": "Stress and Health", "w": ["Relaxed, patient, easy-going", "Tidy, careful, and precise", "Shy, quiet, and withdrawn"], "why": "both"},
  {"a": "Relaxed and easy-going", "id": "psychology_0573", "p": "What is Type B behaviour?", "s": "Stress and Health", "w": ["Competitive and impatient", "Anxious and fearful", "Careful and precise"], "why": "implausible-distractors"},
  {"a": "Acting to change the cause", "id": "psychology_0574", "p": "What is problem-focused coping?", "s": "Stress and Health", "w": ["Managing how you feel about it", "Ignoring the problem for now", "Blaming other people for it"], "why": "both"},
  {"a": "Managing how you feel about it", "id": "psychology_0575", "p": "What is emotion-focused coping?", "s": "Stress and Health", "w": ["Solving the problem quickly", "Acting to remove the cause", "Asking your boss for help"], "why": "both"},
  {"a": "It reduces the harmful effects", "id": "psychology_0576", "p": "How does social support usually affect stress?", "s": "Stress and Health", "w": ["It always makes the stress worse", "It creates new stressors", "It has no effect at all"], "why": "both"},
  {"a": "Exhaustion from long work stress", "id": "psychology_0577", "p": "What is burnout?", "s": "Stress and Health", "w": ["A brief flash of strong anger", "A sudden attack of panic", "A burn caused by heat"], "why": "both"},
  {"a": "A calm state that lowers arousal", "id": "psychology_0578", "p": "What is the relaxation response?", "s": "Stress and Health", "w": ["A rise in heart rate and breathing", "A stage of deep, slow sleep", "A reaction of sudden fear"], "why": "both"},
  {"a": "It generally improves it", "id": "psychology_0579", "p": "What does regular exercise usually do for mood?", "s": "Stress and Health", "w": ["It has no effect on it", "It helps only the young", "It usually worsens it"], "why": "implausible-distractors"},
  {"a": "How mind and behaviour affect health", "id": "psychology_0580", "p": "What does health psychology study?", "s": "Stress and Health", "w": ["How an operation is planned and done", "How new medicines are made", "How hospitals are managed"], "why": "both"},
  {"a": "Long stress raises the risk", "id": "psychology_0581", "p": "What links long-term stress and heart disease?", "s": "Stress and Health", "w": ["Long stress protects the heart", "There is no known link at all", "Only diet affects the heart"], "why": "both"},
  {"a": "Symptoms of stress and anxiety", "id": "psychology_0582", "p": "What has mindfulness meditation been shown to reduce?", "s": "Stress and Health", "w": ["The amount of sleep needed each night", "The ability to pay attention", "Body temperature for good"], "why": "both"},
  {"a": "A prediction that can be tested", "id": "psychology_0583", "p": "What is a hypothesis?", "s": "How Psychology Is Studied", "w": ["A measure of how likely a result is", "A conclusion drawn from results", "A method for choosing a sample"], "why": "both"},
  {"a": "The one the researcher changes", "id": "psychology_0584", "p": "What is the independent variable?", "s": "How Psychology Is Studied", "w": ["The one that could explain results", "The one the researcher measures", "The one held steady throughout"], "why": "both"},
  {"a": "The one measured as the outcome", "id": "psychology_0585", "p": "What is the dependent variable?", "s": "How Psychology Is Studied", "w": ["The one the researcher changes", "The one kept the same for all", "The one that hides a real cause"], "why": "both"},
  {"a": "A group given no active treatment", "id": "psychology_0586", "p": "What is a control group?", "s": "How Psychology Is Studied", "w": ["A group given the real treatment", "A group that runs the study", "A group chosen for its size"], "why": "both"},
  {"a": "Putting people into groups by chance", "id": "psychology_0587", "p": "What is random assignment?", "s": "How Psychology Is Studied", "w": ["Picking the friendliest people first", "Letting people pick their own group", "Putting people into groups by age"], "why": "both"},
  {"a": "It makes the groups alike at the start", "id": "psychology_0588", "p": "Why does random assignment matter?", "s": "How Psychology Is Studied", "w": ["It removes the need for a control group", "It makes the study finish much faster", "It increases the number of people"], "why": "both"},
  {"a": "Neither side knows who got what", "id": "psychology_0589", "p": "What is a double-blind study?", "s": "How Psychology Is Studied", "w": ["Only the participants are unaware", "Only the researchers are unaware", "Nobody writes down the results"], "why": "both"},
  {"a": "Two things that vary together", "id": "psychology_0590", "p": "What is a correlation?", "s": "How Psychology Is Studied", "w": ["A difference between two groups", "One thing that causes another", "A single careful measurement"], "why": "both"},
  {"a": "No, it does not", "id": "psychology_0591", "p": "Does a correlation prove one thing causes the other?", "s": "How Psychology Is Studied", "w": ["Only with large samples", "Yes, if it is strong", "Yes, always"], "why": "implausible-distractors"},
  {"a": "Both measures rise together", "id": "psychology_0592", "p": "What is a positive correlation?", "s": "How Psychology Is Studied", "w": ["Both measures stay exactly equal", "One rises while the other falls", "Neither measure changes at all"], "why": "both"},
  {"a": "One rises while the other falls", "id": "psychology_0593", "p": "What is a negative correlation?", "s": "How Psychology Is Studied", "w": ["Both measures rise together at once", "Neither measure changes at all", "Both measures fall together"], "why": "both"},
  {"a": "An extra factor that could explain it", "id": "psychology_0594", "p": "What is a confounding variable?", "s": "How Psychology Is Studied", "w": ["The factor being measured at the end", "A factor kept the same for everyone", "The factor the researcher changes"], "why": "both"},
  {"a": "A close look at one person or group", "id": "psychology_0595", "p": "What is a case study?", "s": "How Psychology Is Studied", "w": ["A survey of several thousand people", "A test of two matched groups", "A summary of past research"], "why": "both"},
  {"a": "Watching behaviour in its normal setting", "id": "psychology_0596", "p": "What is naturalistic observation?", "s": "How Psychology Is Studied", "w": ["Testing behaviour in a careful laboratory", "Asking people about their behaviour", "Recording behaviour after an event"], "why": "both"},
  {"a": "A sample that mirrors the population", "id": "psychology_0597", "p": "What is a representative sample?", "s": "How Psychology Is Studied", "w": ["A sample chosen only from volunteers", "The largest sample available", "A sample split evenly by age"], "why": "both"},
  {"a": "Agreeing after being told what happens", "id": "psychology_0598", "p": "What is informed consent?", "s": "How Psychology Is Studied", "w": ["Agreeing without being told anything", "Agreeing on behalf of someone else", "Agreeing in return for a payment"], "why": "both"},
  {"a": "Explaining the study afterwards", "id": "psychology_0599", "p": "What is debriefing?", "s": "How Psychology Is Studied", "w": ["Screening people beforehand", "Removing unhelpful results", "Writing the final report"], "why": "both"},
  {"a": "Repeating a study to check it holds", "id": "psychology_0600", "p": "What is replication in research?", "s": "How Psychology Is Studied", "w": ["Doubling the number of people taking part", "Copying another author's wording", "Publishing the same paper twice"], "why": "both"},
  {"a": "The result is unlikely to be chance", "id": "psychology_0601", "p": "What does statistical significance suggest?", "s": "How Psychology Is Studied", "w": ["The result is large and very important", "The study used many participants", "The theory has now been proved"], "why": "both"},
  {"a": "To separate real effects from expectation", "id": "psychology_0602", "p": "Why do researchers use a placebo?", "s": "How Psychology Is Studied", "w": ["To reduce the cost of running a study", "To shorten the study by a few weeks", "To treat more people in less time"], "why": "both"}
]
$fixes$::jsonb) as fix(item)
where question.id = fix.item ->> 'id'
  and question.category_id = 'psychology';

do $validation$
begin
  if (
    select count(*) from public.quiz_questions
    where category_id = 'psychology' and is_active
  ) <> 602 then
    raise exception 'Psychology must still contain exactly 602 active questions';
  end if;

  if exists (
    select 1
    from public.quiz_questions as question
    where question.category_id = 'psychology'
      and (
        cardinality(question.wrong_answers) <> 3
        or (
          select count(distinct lower(trim(answer)))
          from unnest(question.wrong_answers) as answer
        ) <> 3
        or exists (
          select 1
          from unnest(question.wrong_answers) as answer
          where lower(trim(answer)) = lower(trim(question.correct_answer))
        )
      )
  ) then
    raise exception 'Psychology: every question needs three distinct wrong answers';
  end if;

  if exists (
    select 1
    from public.quiz_questions as proposed
    join public.quiz_questions as existing
      on lower(trim(existing.prompt)) = lower(trim(proposed.prompt))
     and existing.id <> proposed.id
    where proposed.category_id = 'psychology'
  ) then
    raise exception 'Psychology: a prompt is already used by another question';
  end if;

  -- The attribution questions are meant to be gone, not merely reworded.
  if exists (
    select 1 from public.quiz_questions
    where category_id = 'psychology' and prompt ilike 'who %'
  ) then
    raise exception 'Psychology should no longer ask who did what';
  end if;
end;
$validation$;
